//! Search, density fitting, and optional relaxation workflow orchestration.
//!
//! The default objective is the historical steric/energy workflow.  A density
//! objective remains extensible, while density fitting is deliberately
//! density-only unless callers opt into a post-fit energy relaxation.

use std::cell::Cell;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::{Duration, Instant};

use glysys::{
    AtomId, ParameterizedSystem, ResidueId, Structure, StructureResidue, SystemBuilder, Vec3,
};
use glysys_opt::{
    DifferentiableObjective, LbfgsConfig, ParticleSeed, ParticleSwarmConfig,
    ParticleSwarmGeneration, ParticleSwarmOutcome, ParticleSwarmProblem,
    lbfgs_minimize_with_progress, particle_swarm_optimize_with_progress,
};
use rayon::prelude::*;
use reglyco_build::{BuildProduct, LinkageDefinition, remove_glycan_at_site};
use reglyco_core::{ClashStatus, SearchConfig, SearchOutcome, SearchSite, SearchSiteResult};
use reglyco_density::{
    DensityFixedRegion, DensityFixedScore, DensityIndexedAtom, DensityKernelProfile,
    DensityMapMetadata, DensityScore, DensityScorer, DensitySigmaCalibration, DensityTarget,
    fast_score::FastDensityContext,
};
use reglyco_ensemble::{
    SearchProgress, build_from_outcome, build_from_outcome_with_angles, search_with_progress,
    steric_score,
};
use reglyco_relax::{
    MovableSelection, RelaxOptions, RelaxProgress, RelaxationDiagnostics, relax_with_progress,
};
use reglyco_report::{Provenance, ReportAnalysis, WorkflowReport};
use reglyco_validate::{ValidationOptions, validate_with_options};

pub type Result<T> = std::result::Result<T, RefineError>;

static DIRECT_LOCAL_COMPARE_COUNT: AtomicUsize = AtomicUsize::new(0);

#[derive(Debug, thiserror::Error)]
pub enum RefineError {
    #[error(transparent)]
    Ensemble(#[from] reglyco_ensemble::EnsembleError),
    #[error(transparent)]
    Build(#[from] reglyco_core::ReGlycoError),
    #[error(transparent)]
    Density(#[from] reglyco_density::DensityError),
    #[error(transparent)]
    Relax(#[from] reglyco_relax::RelaxError),
    #[error(transparent)]
    GlySys(#[from] glysys::BuildError),
    #[error("density fitting exhausted its evaluation limit before finding a valid pose")]
    DensityNoPose,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DensitySearchStrategy {
    Adaptive,
    Swarm,
    Staged,
}

/// Amount of evidence-driven escalation permitted by the adaptive fitter.
/// None of these modes imposes a wall-clock limit; they differ only in the
/// number of distinct ensemble basins and coupled linkage proposals explored.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DensityEffort {
    Fast,
    #[default]
    Adaptive,
    Deep,
}

/// Deep-mode implementation selector. `Frontier` grows the requested tree
/// from the attachment using residual-density evidence; `LegacyGlobal` keeps
/// the previous whole-tree search available for diagnostics and regression
/// comparison.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DensityDeepStrategy {
    #[default]
    Frontier,
    LegacyGlobal,
    /// Detect residue-sized density components first, then connect them with
    /// the requested glycan topology.  This remains experimental so the
    /// existing deep strategies can be reproduced exactly.
    RingGraph,
}

/// Live events emitted by [`refine_with_progress`].  The library remains
/// silent when callers use [`refine`], while command-line clients can render
/// these events without duplicating the search or relaxation loops.
#[derive(Debug, Clone)]
pub enum RefineProgress {
    Phase {
        name: &'static str,
    },
    Search(SearchProgress),
    DensityStarted {
        max_evaluations: Option<usize>,
        branch_count: usize,
    },
    DensityStageStarted {
        stage: &'static str,
        candidates: usize,
        planned_evaluations: usize,
    },
    DensityBatchProgress {
        stage: &'static str,
        evaluated: usize,
        planned: usize,
        valid: usize,
        best_correlation: Option<f64>,
        best_support: Option<f64>,
        elapsed_seconds: f64,
    },
    DensityStageFinished {
        stage: &'static str,
        evaluations: usize,
        retained: usize,
        best_correlation: f64,
        best_support: f64,
    },
    DensityEvaluation {
        evaluation: usize,
        max_evaluations: Option<usize>,
        step_degrees: f64,
        parameter: String,
        correlation: Option<f64>,
        accepted: bool,
        best_correlation: f64,
    },
    DensityStepFinished {
        step_degrees: f64,
        evaluations: usize,
        best_correlation: f64,
    },
    DensityFinished {
        evaluations: usize,
        best_correlation: f64,
        seconds: f64,
    },
    Relax(RelaxProgress),
}

/// Top-level refinement objective.  `StericEnergy` preserves the pre-density
/// ReGlyco behaviour; the density variant is intentionally extensible so a
/// future SAXS objective can be added without changing `RefineRequest`.
#[derive(Debug, Clone, Default)]
pub enum RefineObjective {
    #[default]
    StericEnergy,
    Density(DensityRefinementConfig),
}

#[derive(Debug, Clone)]
pub struct DensityRefinementConfig {
    pub scorer: DensityScorer,
    pub map_url: Option<String>,
    pub difference_scorer: Option<DensityScorer>,
    pub difference_map_url: Option<String>,
    pub sigma_calibration: Option<DensitySigmaCalibration>,
    /// Targets may contain only `site` and an empty residue list.  In that
    /// form the exact tree is resolved from each candidate's GlySys metadata,
    /// which is important after replacing a glycan with a new chain.
    pub targets: Vec<DensityTarget>,
    pub torsion_steps_degrees: Vec<f64>,
    pub optimize_glycosidic_torsions: bool,
    /// Optional emergency evaluation failsafe.  The normal stopping rule is
    /// the phase deadline, not an arbitrary objective-call count.
    pub max_evaluations: Option<usize>,
    pub search_strategy: DensitySearchStrategy,
    pub effort: DensityEffort,
    pub deep_strategy: DensityDeepStrategy,
    /// Optional emergency wall-clock guard. Adaptive fitting normally stops
    /// from evidence exhaustion and numerical convergence, not elapsed time.
    pub time_limit_seconds: Option<f64>,
    pub support_threshold: f64,
    pub top_candidates: usize,
    /// Posterior mass covered by the structurally diverse candidate bundle.
    pub credible_mass: f64,
    /// Hard cap on alternate models in the credible set.
    pub max_alternates: usize,
    /// Run the ordinary local energy relaxation after density fitting.
    /// Density mode defaults to false so fitting does not parameterize a
    /// force-field system or report an unrelated energy objective.
    pub post_relax_energy: bool,
    /// Crop margin used for the observed/calculated/mask visualization maps.
    pub crop_margin_angstrom: f64,
}

impl DensityRefinementConfig {
    pub fn new(scorer: DensityScorer, targets: Vec<DensityTarget>) -> Self {
        Self {
            scorer,
            map_url: None,
            difference_scorer: None,
            difference_map_url: None,
            sigma_calibration: None,
            targets,
            torsion_steps_degrees: vec![10.0, 5.0, 2.0, 1.0],
            optimize_glycosidic_torsions: true,
            max_evaluations: None,
            search_strategy: DensitySearchStrategy::Adaptive,
            effort: DensityEffort::Adaptive,
            deep_strategy: DensityDeepStrategy::Frontier,
            time_limit_seconds: None,
            support_threshold: 0.60,
            top_candidates: 10,
            credible_mass: 0.95,
            max_alternates: 10,
            post_relax_energy: false,
            crop_margin_angstrom: 8.0,
        }
    }
}

