fn default_density_credible_mass() -> f64 {
    0.95
}

fn classify_arm_evidence(
    density_gain: f64,
    bic_penalty: f64,
    top_mode_posterior: f64,
    linkage_path_support: f64,
    search_improved: bool,
) -> &'static str {
    if density_gain < 0.0 || !search_improved {
        "ensemble_prior_determined"
    } else if density_gain > bic_penalty
        && top_mode_posterior >= 0.75
        && linkage_path_support >= 0.60
    {
        "density_determined"
    } else {
        "ambiguous"
    }
}

