/// Generate a bounded set of topology-authorized ring-capture proposals for
/// Adaptive.  Every proposal moves one residue with its incoming linkage (and
/// the immediately preceding parent linkage when present), so a distal ring
/// cannot jump independently to a peak.  The detector is candidate-independent
/// and the exact complete-tree scorer remains the acceptance gate.
fn adaptive_ring_guided_candidate(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    initial: &[f64],
    vdw: &VdwClashContext,
) -> (Vec<f64>, usize) {
    if problem.deadline_reached() {
        return (initial.to_vec(), 0);
    }
    if problem.ring_hypotheses.is_empty() {
        return (initial.to_vec(), 1);
    }
    let mut proposals = vec![initial.to_vec()];
    for arm in connected_arm_definitions(problem.branches).iter().take(2) {
        if problem.deadline_reached() {
            break;
        }
        for residue in &arm.residues {
            if problem.deadline_reached() {
                break;
            }
            let mut axes = problem
                .branches
                .iter()
                .enumerate()
                .filter_map(|(index, branch)| {
                    (branch.child_residue == *residue && arm.axes.contains(&index)).then_some(index)
                })
                .collect::<Vec<_>>();
            if let Some(parent) = problem
                .branches
                .iter()
                .find(|branch| branch.child_residue == *residue)
                .map(|branch| branch.parent_residue.clone())
            {
                if let Some(parent_axis) = problem
                    .branches
                    .iter()
                    .position(|branch| branch.child_residue == parent)
                {
                    axes.push(parent_axis);
                }
            }
            axes.sort_unstable();
            axes.dedup();
            if axes.is_empty() {
                continue;
            }
            proposals.extend(frontier_ring_guided_positions(
                problem, context, initial, residue, &axes, 4,
            ));
        }
    }
    proposals.sort_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal));
    proposals.dedup();
    proposals.truncate(32);
    let mut scored = proposals
        .par_iter()
        .filter(|_| !problem.deadline_reached())
        .map(|proposal| {
            (
                pattern_objective_with_vdw(problem, context, proposal, vdw),
                proposal.clone(),
            )
        })
        .collect::<Vec<_>>();
    scored.sort_by(|left, right| {
        right.0.total_cmp(&left.0).then_with(|| {
            left.1
                .partial_cmp(&right.1)
                .unwrap_or(std::cmp::Ordering::Equal)
        })
    });
    scored
        .into_iter()
        .next()
        .map(|(_, position)| (position, proposals.len()))
        .unwrap_or_else(|| (initial.to_vec(), 1))
}

/// Expand the Adaptive arm beam with a small, map-derived ring dictionary.
/// Native GlycoShape modes remain the default proposal distribution; these
/// candidates are only the bounded escape hatch needed when the native arm
/// coverage oracle proves that no conformer can reach a supported ring.  A
/// detector hypothesis supplies a ring centre/orientation, while the
/// topology-aware registration converts the resulting complete subtree back
/// into ordinary linkage variables.  The final fixed-ROI scorer, not the
/// detector strength, decides whether a candidate survives.
fn adaptive_density_ring_capture(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    initial: &[f64],
    native_torsions: &BTreeMap<DensityParticleContext, Vec<f64>>,
    vdw: &VdwClashContext,
    targets: &[DensityTarget],
) -> (Vec<(Vec<f64>, Structure, DensityScore, f64)>, usize) {
    if problem.deadline_reached() || problem.ring_hypotheses.is_empty() {
        return (Vec::new(), 0);
    }
    let arms = connected_arm_definitions(problem.branches);
    if arms.is_empty() {
        return (Vec::new(), 0);
    }
    let mut arm_options = Vec::<(ConnectedArm, Vec<(f64, Vec<f64>)>)>::new();
    let mut evaluations = 0usize;
    for arm in arms.iter().take(2) {
        if problem.deadline_reached() {
            break;
        }
        let child = arm.root_residue.clone();
        let child_name = problem
            .base_template
            .residues()
            .into_iter()
            .find(|record| record.id == child)
            .map(|record| record.name);
        let mut hypotheses = problem
            .ring_hypotheses
            .iter()
            .filter(|hypothesis| {
                hypothesis.site == problem.targets[0].site
                    && ring_hypothesis_matches_residue(hypothesis, child_name.as_deref())
            })
            .collect::<Vec<_>>();
        hypotheses.sort_by(|left, right| {
            right
                .normalized_score
                .total_cmp(&left.normalized_score)
                .then_with(|| left.component_id.cmp(&right.component_id))
        });
        // Keep enough components for a weak/intermediate ring, but avoid
        // turning this capture path into another all-voxel search.
        hypotheses.truncate(32);
        let mut options = hypotheses
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|hypothesis| {
                let position = frontier_ring_hypothesis_position(
                    problem,
                    context,
                    initial,
                    &child,
                    hypothesis,
                    native_torsions,
                )?;
                let score =
                    problem.fast_evidence_objective_position(context, &position, targets)?;
                Some((score, position))
            })
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(options.len());
        // If the rigid SO(3) registration cannot be represented by the
        // linkage kinematics, retain a second finite route that only targets
        // the detected ring centre.  The coordinate-descent helper moves the
        // authorized parent/child axes and never translates an atom outside
        // the chemical model; exact scoring below still rejects disconnected
        // or clashing peaks.
        let root_axes = problem
            .branches
            .iter()
            .enumerate()
            .filter_map(|(axis, branch)| (branch.child_residue == child).then_some(axis))
            .collect::<Vec<_>>();
        let centre_positions =
            frontier_ring_guided_positions(problem, context, initial, &child, &root_axes, 16);
        let centre_options = centre_positions
            .into_par_iter()
            .filter_map(|position| {
                let score =
                    problem.fast_evidence_objective_position(context, &position, targets)?;
                Some((score, position))
            })
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(centre_options.len());
        options.sort_by(|left, right| right.0.total_cmp(&left.0));
        options.truncate(4);
        let mut centre_options = centre_options;
        centre_options.sort_by(|left, right| right.0.total_cmp(&left.0));
        centre_options.truncate(4);
        options.extend(centre_options);
        // Complete-arm proposals from the detected ring sequence.  The arm
        // root alone may place correctly while every descendant remains on
        // its native geometry; this path places each ring relative to its
        // already-placed parent so a complete arm can be assembled from
        // density even when GlycoShape contains no matching correlated mode.
        let sequence_options =
            frontier_ring_sequence_arm_positions(problem, context, initial, arm, native_torsions)
                .into_par_iter()
                .filter(|_| !problem.deadline_reached())
                .filter_map(|position| {
                    let score =
                        problem.fast_evidence_objective_position(context, &position, targets)?;
                    Some((score, position))
                })
                .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(sequence_options.len());
        let mut sequence_options = sequence_options;
        sequence_options.sort_by(|left, right| {
            right.0.total_cmp(&left.0).then_with(|| {
                left.1
                    .partial_cmp(&right.1)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        });
        sequence_options.truncate(4);
        for sequence in sequence_options {
            if !options.iter().any(|(_, existing)| existing == &sequence.1) {
                options.push(sequence);
            }
        }
        if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some() {
            eprintln!(
                "adaptive-density-ring-arm: arm={} hypotheses={} registered={}",
                arm.label,
                hypotheses.len(),
                options.len()
            );
        }
        options.sort_by(|left, right| {
            right.0.total_cmp(&left.0).then_with(|| {
                left.1
                    .partial_cmp(&right.1)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        });
        options.truncate(8);
        if !options.is_empty() {
            arm_options.push((arm.clone(), options));
        }
    }
    if arm_options.is_empty() {
        return (Vec::new(), evaluations);
    }

    // Combine sibling arms before exact scoring.  Each option already carries
    // a full position vector, so only the axes owned by that arm are copied;
    // the fitted core and the other arm remain unchanged.
    let mut combinations = Vec::<(f64, Vec<f64>)>::new();
    if arm_options.len() == 1 {
        combinations.extend(arm_options[0].1.iter().cloned());
    } else {
        for left in &arm_options[0].1 {
            for right in &arm_options[1].1 {
                let mut position = initial.to_vec();
                for axis in &arm_options[0].0.axes {
                    if let Some(value) = left.1.get(problem.angle_dimensions + *axis) {
                        position[problem.angle_dimensions + *axis] = *value;
                    }
                }
                for axis in &arm_options[1].0.axes {
                    if let Some(value) = right.1.get(problem.angle_dimensions + *axis) {
                        position[problem.angle_dimensions + *axis] = *value;
                    }
                }
                let score = problem
                    .fast_evidence_objective_position(context, &position, targets)
                    .unwrap_or(f64::NEG_INFINITY);
                combinations.push((score, position));
            }
        }
    }
    evaluations = evaluations.saturating_add(combinations.len());
    combinations.sort_by(|left, right| {
        right.0.total_cmp(&left.0).then_with(|| {
            left.1
                .partial_cmp(&right.1)
                .unwrap_or(std::cmp::Ordering::Equal)
        })
    });
    combinations.truncate(8);

    let ring_clash_limit = if std::env::var_os("REGLYCO_DENSITY_DEBUG_ALLOW_RING_CLASH").is_some() {
        2.50
    } else {
        1.20
    };
    let mut exact = combinations
        .into_par_iter()
        .filter(|_| !problem.deadline_reached())
        .filter_map(|(_, mut position)| {
            let mut structure = problem.structure(context, &position)?.0;
            let mut steric = 1.0;
            let overlap = max_vdw_overlap_pair(&structure, vdw).0;
            if overlap > ring_clash_limit {
                // The native beam also tolerates a temporary overlap and
                // repairs it with bounded torsion steps before ranking.
                // Apply the same repair here so a ring-assembled arm is not
                // discarded before its clash can be resolved by local
                // geometry.
                let (repaired, _) =
                    resolve_density_overlaps(problem, context, &position, vdw, targets);
                let Some(repaired_structure) = problem.structure(context, &repaired) else {
                    return None;
                };
                let (repaired_structure, repaired_steric) = repaired_structure;
                if max_vdw_overlap_pair(&repaired_structure, vdw).0 > ring_clash_limit {
                    if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some() {
                        let pair =
                            max_vdw_overlap_pair(&repaired_structure, vdw).1.map(|(left, right)| {
                                repaired_structure
                                    .atom(left)
                                    .zip(repaired_structure.atom(right))
                                    .map(|(l, r)| {
                                        format!(
                                            "{}:{}:{} - {}:{}:{}",
                                            l.residue, l.name, l.element, r.residue, r.name, r.element
                                        )
                                    })
                                    .unwrap_or_else(|| format!("{left:?}-{right:?}"))
                            });
                        let centers = arm_options
                            .iter()
                            .flat_map(|(arm, _)| arm.residues.iter())
                            .filter_map(|residue| {
                                residue_ring_center(&repaired_structure, residue).map(|center| {
                                    format!(
                                        "{residue}:({:.1},{:.1},{:.1})",
                                        center[0], center[1], center[2]
                                    )
                                })
                            })
                            .collect::<Vec<_>>()
                            .join(" ");
                        eprintln!(
                            "adaptive-density-ring-reject: overlap={overlap:.3} repaired_overlap={:.3} pair={pair:?} centers={}",
                            max_vdw_overlap_pair(&repaired_structure, vdw).0,
                            centers
                        );
                    }
                    return None;
                }
                position = repaired;
                structure = repaired_structure;
                steric = repaired_steric;
            }
            let score = problem.density_score(&structure, targets)?;
            Some((position, structure, score, steric, overlap))
        })
        .collect::<Vec<_>>();
    evaluations = evaluations.saturating_add(exact.len());
    if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some() {
        let minimum_overlap = exact
            .iter()
            .map(|candidate| candidate.4)
            .fold(f64::INFINITY, f64::min);
        eprintln!(
            "adaptive-density-ring-combinations: limit={ring_clash_limit:.2} accepted={} min_overlap={minimum_overlap:.4}",
            exact.len()
        );
    }
    exact.sort_by(|left, right| {
        let left_value = left.2.correlation
            + 1.0e-4 * left.2.likelihood_gain
            + 2.0e-5 * left.2.heldout_likelihood_gain;
        let right_value = right.2.correlation
            + 1.0e-4 * right.2.likelihood_gain
            + 2.0e-5 * right.2.heldout_likelihood_gain;
        right_value.total_cmp(&left_value).then_with(|| {
            left.0
                .partial_cmp(&right.0)
                .unwrap_or(std::cmp::Ordering::Equal)
        })
    });
    (
        exact
            .into_iter()
            .map(|(position, structure, score, steric, _)| (position, structure, score, steric))
            .collect(),
        evaluations,
    )
}

/// Diagnostic density-first counterpart to the torsion capture above.  It
/// keeps the complete detected subtree in Cartesian space long enough to test
/// whether the internal-coordinate model itself is the bottleneck.  The
/// subtree is still a rigid chemically valid GlycoShape template, and every
/// candidate is checked for its requested parent linkage, clashes, and exact
/// fixed-ROI score.  This path is not used for ranking until its coverage is
/// proven; it is the oracle needed to distinguish a bad torsion model from a
/// bad density detector.
fn adaptive_density_ring_direct_capture(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    initial: &[f64],
    vdw: &VdwClashContext,
    targets: &[DensityTarget],
) -> (Vec<(Structure, DensityScore, f64)>, usize) {
    if problem.deadline_reached() || problem.ring_hypotheses.is_empty() {
        return (Vec::new(), 0);
    }
    let Some(base_structure) = problem.structure(context, initial).map(|entry| entry.0) else {
        return (Vec::new(), 0);
    };
    let Some(base_positions) = problem.coordinate_positions(context, initial) else {
        return (Vec::new(), 0);
    };
    let arms = connected_arm_definitions(problem.branches);
    let mut options = Vec::<(ConnectedArm, Vec<(f64, BTreeMap<AtomId, Vec3>)>)>::new();
    let mut evaluations = 0usize;
    for arm in arms.iter().take(2) {
        let child = arm.root_residue.clone();
        let root_branch = problem.branches.iter().find(|branch| {
            branch.parent_residue == arm.parent_residue && branch.child_residue == child
        });
        let sequences = frontier_ring_sequence_direct_positions(problem, context, initial, arm);
        if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some() {
            eprintln!(
                "adaptive-direct-ring-sequence: arm={} sequences={}",
                arm.label,
                sequences.len()
            );
            if let Some(first) = sequences.first() {
                let centers = arm
                    .residues
                    .iter()
                    .filter_map(|residue| {
                        residue_ring_center_positions(problem, first, residue).map(|center| {
                            format!(
                                "{residue}:({:.1},{:.1},{:.1})",
                                center[0], center[1], center[2]
                            )
                        })
                    })
                    .collect::<Vec<_>>()
                    .join(" ");
                eprintln!("adaptive-direct-ring-sequence-first: {centers}");
            }
        }
        let mut arm_options = sequences
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|hypothesis| {
                if let Some(branch) = root_branch {
                    let length = linkage_bond_length(problem.base_template, hypothesis, branch)?;
                    // A direct ring pose is allowed to leave the internal
                    // torsion manifold, but not to break its parent linkage.
                    if std::env::var_os("REGLYCO_DENSITY_DEBUG_ALLOW_RING_BOND").is_none()
                        && !(0.9..=2.5).contains(&length)
                    {
                        return None;
                    }
                }
                let score = problem.fast_evidence_objective_positions(hypothesis, targets)?;
                Some((score, hypothesis.clone()))
            })
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(arm_options.len());
        arm_options.sort_by(|left, right| right.0.total_cmp(&left.0));
        arm_options.truncate(12);
        if !arm_options.is_empty() {
            options.push((arm.clone(), arm_options));
        }
    }
    if options.is_empty() {
        return (Vec::new(), evaluations);
    }

    let mut combinations = Vec::<BTreeMap<AtomId, Vec3>>::new();
    let merge = |selected: &[(&ConnectedArm, &BTreeMap<AtomId, Vec3>)]| {
        let mut positions = base_positions.clone();
        for (arm, candidate) in selected {
            let residues = arm.residues.iter().collect::<BTreeSet<_>>();
            for atom in problem.base_template.atoms() {
                if residues.contains(&atom.residue) {
                    if let Some(position) = candidate.get(&atom.id) {
                        positions.insert(atom.id, *position);
                    }
                }
            }
        }
        positions
    };
    if options.len() == 1 {
        combinations.extend(
            options[0]
                .1
                .iter()
                .map(|(_, positions)| merge(&[(&options[0].0, positions)])),
        );
    } else {
        for left in &options[0].1 {
            for right in &options[1].1 {
                combinations.push(merge(&[
                    (&options[0].0, &left.1),
                    (&options[1].0, &right.1),
                ]));
            }
        }
    }
    evaluations = evaluations.saturating_add(combinations.len());
    let clash_limit = if std::env::var_os("REGLYCO_DENSITY_DEBUG_ALLOW_RING_CLASH").is_some() {
        2.50
    } else {
        1.20
    };
    let mut exact = combinations
        .par_iter()
        .filter(|_| !problem.deadline_reached())
        .filter_map(|positions| {
            let mut structure = base_structure.clone();
            structure
                .set_atom_positions(positions.iter().map(|(atom, position)| (*atom, *position)))
                .ok()?;
            let overlap = max_vdw_overlap_pair(&structure, vdw).0;
            if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some() {
                let pair = max_vdw_overlap_pair(&structure, vdw)
                    .1
                    .map(|(left, right)| {
                        structure
                            .atom(left)
                            .zip(structure.atom(right))
                            .map(|(l, r)| {
                                format!(
                                    "{}:{}:{} - {}:{}:{}",
                                    l.residue, l.name, l.element, r.residue, r.name, r.element
                                )
                            })
                            .unwrap_or_else(|| format!("{left:?}-{right:?}"))
                    });
                eprintln!("adaptive-direct-ring-raw: overlap={overlap:.3} pair={pair:?}");
            }
            if std::env::var_os("REGLYCO_DENSITY_DIRECT_SAVE").is_some()
                && let Some(path) = std::env::var_os("REGLYCO_DENSITY_DIRECT_SAVE")
            {
                let _ = std::fs::write(path, structure.to_pdb_string());
            }
            if overlap > clash_limit {
                return None;
            }
            let score = problem.density_score(&structure, targets)?;
            Some((structure, score, overlap))
        })
        .collect::<Vec<_>>();
    evaluations = evaluations.saturating_add(exact.len());
    exact.sort_by(|left, right| {
        let left_value = left.1.correlation
            + 1.0e-4 * left.1.likelihood_gain
            + 2.0e-5 * left.1.heldout_likelihood_gain;
        let right_value = right.1.correlation
            + 1.0e-4 * right.1.likelihood_gain
            + 2.0e-5 * right.1.heldout_likelihood_gain;
        right_value.total_cmp(&left_value)
    });
    if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some() {
        if let Some((structure, score, overlap)) = exact.first() {
            let residues = targets
                .iter()
                .flat_map(|target| target.glycan_residues.iter())
                .collect::<Vec<_>>();
            let centers = residues
                .iter()
                .filter_map(|residue| {
                    residue_ring_center(structure, residue).map(|center| {
                        format!(
                            "{residue}:({:.1},{:.1},{:.1})",
                            center[0], center[1], center[2]
                        )
                    })
                })
                .collect::<Vec<_>>()
                .join(" ");
            eprintln!(
                "adaptive-direct-ring-best: accepted={} cc={:.6} overlap={overlap:.3} centers={}",
                exact.len(),
                score.correlation,
                centers
            );
        } else {
            eprintln!("adaptive-direct-ring-best: accepted=0");
        }
    }
    (exact, evaluations)
}

fn adaptive_arm_offset_trials(
    position: &[f64],
    groups: &[usize],
    angle_dimensions: usize,
    deltas: &[f64],
) -> Vec<Vec<f64>> {
    fn expand(
        seed: &[f64],
        groups: &[usize],
        angle_dimensions: usize,
        deltas: &[f64],
        index: usize,
        current: &mut Vec<f64>,
        output: &mut Vec<Vec<f64>>,
    ) {
        if index == groups.len() {
            output.push(current.clone());
            return;
        }
        let dimension = angle_dimensions + groups[index];
        for delta in deltas {
            current[dimension] = wrap_degrees(seed[dimension] + *delta);
            expand(
                seed,
                groups,
                angle_dimensions,
                deltas,
                index + 1,
                current,
                output,
            );
        }
    }
    let mut output = Vec::new();
    let mut current = position.to_vec();
    expand(
        position,
        groups,
        angle_dimensions,
        deltas,
        0,
        &mut current,
        &mut output,
    );
    output
}

/// Cross the small parent/child saddles that remain after a native arm mode
/// is selected.  Coordinate-wise polishing cannot move two linkages together
/// when every individual step lowers the complete-tree score; this bounded
/// trust-region pass enumerates only ±30/15° offsets for one residue or one
/// adjacent parent/child block, keeping the attachment/core frozen.
fn adaptive_correlated_arm_polish(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    initial: &[f64],
    vdw: &VdwClashContext,
    arms: &[ConnectedArm],
) -> (Vec<f64>, usize) {
    if problem.deadline_reached() {
        return (initial.to_vec(), 0);
    }
    let mut point = initial.to_vec();
    let mut best = pattern_objective_with_vdw(problem, context, &point, vdw);
    let mut evaluations = 1usize;
    for arm in arms.iter().take(2) {
        if problem.deadline_reached() {
            break;
        }
        let mut groups = Vec::<Vec<usize>>::new();
        for residue in &arm.residues {
            let group = arm
                .axes
                .iter()
                .copied()
                .filter(|axis| problem.branches[*axis].child_residue == *residue)
                .collect::<Vec<_>>();
            if !group.is_empty() {
                groups.push(group);
            }
        }
        // Native residue IDs are deterministic, but use branch order as a
        // stable fallback when a topology has insertion-coded residues.
        if groups.is_empty() {
            groups.push(arm.axes.clone());
        }
        // Keep the trust region sparse, but wide enough to cross the
        // correlated saddle seen in 5KZC.  The previous +/-20 grid was fast
        // but could not reach the good native arm mode (it needs roughly a
        // 30-degree parent move coupled to a 15-degree child move).  Three
        // points per active torsion still avoid the combinatorial old sweep.
        for deltas in [&[-30.0, 0.0, 30.0][..], &[-15.0, 0.0, 15.0][..]] {
            if problem.deadline_reached() {
                break;
            }
            for group in &groups {
                if problem.deadline_reached() {
                    break;
                }
                if group.len() > 3 {
                    continue;
                }
                let trials =
                    adaptive_arm_offset_trials(&point, group, problem.angle_dimensions, deltas);
                let mut scored = trials
                    .par_iter()
                    .filter(|_| !problem.deadline_reached())
                    .map(|trial| {
                        // Do not impose a hard clash gate on an intermediate
                        // trust-region point.  A connected arm can have to pass
                        // through a transient overlap before the coupled move
                        // reaches a clean pose (the 5KZC alpha-1,6 saddle is an
                        // example).  The fixed objective carries a soft overlap
                        // penalty, while `prepare` below is the hard validation
                        // gate for anything that can be selected or exported.
                        let value = problem
                            .structure(context, trial)
                            .map(|(structure, full_steric)| {
                                pattern_objective_structure(&structure, full_steric, problem, vdw)
                            })
                            .unwrap_or(f64::NEG_INFINITY);
                        (value, trial.clone())
                    })
                    .collect::<Vec<_>>();
                evaluations = evaluations.saturating_add(scored.len());
                if problem.deadline_reached() {
                    break;
                }
                scored.sort_by(|left, right| {
                    right.0.total_cmp(&left.0).then_with(|| {
                        left.1
                            .partial_cmp(&right.1)
                            .unwrap_or(std::cmp::Ordering::Equal)
                    })
                });
                if let Some((score, trial)) = scored.into_iter().next()
                    && score > best + 1.0e-4
                {
                    best = score;
                    point = trial;
                }
            }
            // Couple adjacent levels only at the fine trust-region scale.
            for pair in groups.windows(2) {
                if problem.deadline_reached() {
                    break;
                }
                let mut combined = pair[0].clone();
                combined.extend(pair[1].iter().copied());
                combined.sort_unstable();
                combined.dedup();
                if combined.len() > 5 {
                    continue;
                }
                let trials =
                    adaptive_arm_offset_trials(&point, &combined, problem.angle_dimensions, deltas);
                let mut scored = trials
                    .par_iter()
                    .filter(|_| !problem.deadline_reached())
                    .map(|trial| {
                        let value = problem
                            .structure(context, trial)
                            .map(|(structure, full_steric)| {
                                pattern_objective_structure(&structure, full_steric, problem, vdw)
                            })
                            .unwrap_or(f64::NEG_INFINITY);
                        (value, trial.clone())
                    })
                    .collect::<Vec<_>>();
                evaluations = evaluations.saturating_add(scored.len());
                if problem.deadline_reached() {
                    break;
                }
                scored.sort_by(|left, right| {
                    right.0.total_cmp(&left.0).then_with(|| {
                        left.1
                            .partial_cmp(&right.1)
                            .unwrap_or(std::cmp::Ordering::Equal)
                    })
                });
                if let Some((score, trial)) = scored.into_iter().next()
                    && score > best + 1.0e-4
                {
                    best = score;
                    point = trial;
                }
            }
        }
    }
    (point, evaluations)
}

fn exhaustive_frontier_search() -> bool {
    std::env::var_os("REGLYCO_ADAPTIVE_EXHAUSTIVE").is_some()
        || std::env::var_os("REGLYCO_ADAPTIVE_FRONTIER_EXHAUSTIVE").is_some()
}

/// Fast residue-frontier correction used by normal Adaptive mode.
///
/// A linkage is considered only after its parent linkage has been accepted.
/// Accepted axes are never reopened by a later child, so an attractive distal
/// peak cannot make an arm skip its intervening density.  Unlike the former
/// per-child Cartesian product this evaluates a small one-dimensional trust
/// region and, only when needed, a 3x3 parent/child saddle.  Every candidate
/// uses the same final fixed ROI and the same profiled likelihood, which keeps
/// the frontier both deterministic and candidate-independent.
fn adaptive_frozen_frontier_refine(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    initial: &[f64],
    vdw: &VdwClashContext,
) -> (Vec<f64>, usize) {
    let Some(region) = problem.fixed_region else {
        return (initial.to_vec(), 0);
    };
    let score_value = |score: &DensityFixedScore| {
        score.likelihood_gain
            + 0.75 * score.heldout_likelihood_gain
            + 20.0 * score.protein_adjusted_correlation
    };
    let Some((initial_structure, _)) = problem.structure(context, initial) else {
        return (initial.to_vec(), 0);
    };
    let target_atoms = initial_structure
        .atoms()
        .into_iter()
        .filter(|atom| {
            problem
                .targets
                .iter()
                .any(|target| target.glycan_residues.contains(&atom.residue))
                && !atom.element.eq_ignore_ascii_case("H")
        })
        .map(|atom| atom.id)
        .collect::<BTreeSet<_>>();
    let quick_score = |structure: &Structure| {
        problem
            .scorer
            .atom_local_evidence(structure, &target_atoms)
            .map(|evidence| evidence.score)
            .unwrap_or(f64::NEG_INFINITY)
    };
    let Some(mut current_score) = problem
        .scorer
        .score_fixed_region(region, &initial_structure, problem.targets)
        .ok()
    else {
        return (initial.to_vec(), 1);
    };
    let mut point = initial.to_vec();
    let mut evaluations = 1usize;

    // Root/attachment variables are the first frontier.  They are allowed a
    // small registration move before any glycosidic branch is considered;
    // after this block they are frozen for the remainder of the pass.
    let mut root_axes = (0..problem.angle_dimensions).collect::<Vec<_>>();
    root_axes.sort_unstable();
    let root_offsets = if exhaustive_frontier_search() {
        vec![-20.0_f64, -10.0, 0.0, 10.0, 20.0]
    } else {
        vec![-10.0_f64, 0.0, 10.0]
    };
    for axis in root_axes {
        let mut quick_candidates = Vec::new();
        for offset in &root_offsets {
            let mut trial = point.clone();
            trial[axis] = wrap_degrees(trial[axis] + *offset);
            let Some((structure, _)) = problem.structure(context, &trial) else {
                continue;
            };
            if max_vdw_overlap_pair(&structure, vdw).0 > 1.20 {
                continue;
            }
            quick_candidates.push((quick_score(&structure), trial));
        }
        quick_candidates.sort_by(|left, right| {
            right.0.total_cmp(&left.0).then_with(|| {
                left.1
                    .partial_cmp(&right.1)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        });
        let mut candidates = Vec::new();
        for (_, trial) in quick_candidates.into_iter().take(2) {
            let Some((structure, _)) = problem.structure(context, &trial) else {
                continue;
            };
            let Ok(score) = problem
                .scorer
                .score_fixed_region(region, &structure, problem.targets)
            else {
                continue;
            };
            evaluations = evaluations.saturating_add(1);
            candidates.push((score_value(&score), score, trial));
        }
        if let Some((value, score, trial)) = candidates.into_iter().max_by(|left, right| {
            left.0.total_cmp(&right.0).then_with(|| {
                right
                    .2
                    .partial_cmp(&left.2)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        }) && value > score_value(&current_score) + 1.0e-4
            && score.heldout_likelihood_gain + 1.0e-4 >= current_score.heldout_likelihood_gain
        {
            point = trial;
            current_score = score;
        }
    }

    let mut order = (0..problem.branches.len()).collect::<Vec<_>>();
    order.sort_by(|left, right| {
        branch_depth(problem.branches, *left)
            .cmp(&branch_depth(problem.branches, *right))
            .then_with(|| {
                problem.branches[*left]
                    .label
                    .cmp(&problem.branches[*right].label)
            })
            .then_with(|| left.cmp(right))
    });
    let exhaustive = exhaustive_frontier_search();
    let offsets = if exhaustive {
        vec![-120.0, -60.0, -30.0, 0.0, 30.0, 60.0, 120.0]
    } else {
        vec![-30.0, 0.0, 30.0]
    };
    for branch_index in order {
        let dimension = problem.angle_dimensions + branch_index;
        if dimension >= point.len() {
            continue;
        }
        let branch = &problem.branches[branch_index];
        let mut quick_candidates = Vec::new();
        for offset in &offsets {
            let mut trial = point.clone();
            trial[dimension] = wrap_degrees(trial[dimension] + *offset);
            let Some((structure, _)) = problem.structure(context, &trial) else {
                continue;
            };
            if max_vdw_overlap_pair(&structure, vdw).0 > 1.20 {
                continue;
            }
            quick_candidates.push((quick_score(&structure), trial));
        }

        quick_candidates.sort_by(|left, right| {
            right.0.total_cmp(&left.0).then_with(|| {
                left.1
                    .partial_cmp(&right.1)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        });
        let child_targets = problem
            .targets
            .iter()
            .map(|target| DensityTarget {
                site: target.site.clone(),
                glycan_residues: vec![branch.child_residue.clone()],
            })
            .collect::<Vec<_>>();
        let child_region = problem.structure(context, &point).and_then(|(base, _)| {
            let refs = vec![&base];
            problem.scorer.fixed_region(&refs, &child_targets, 8.0).ok()
        });
        let mut local_candidates = Vec::new();
        for (_, trial) in quick_candidates
            .into_iter()
            .take(if exhaustive { 4 } else { 3 })
        {
            let Some((candidate, _)) = problem.structure(context, &trial) else {
                continue;
            };
            let Some(local_score) = child_region.as_ref().and_then(|local_region| {
                problem
                    .scorer
                    .score_fixed_region(local_region, &candidate, &child_targets)
                    .ok()
            }) else {
                continue;
            };
            evaluations = evaluations.saturating_add(1);
            local_candidates.push((score_value(&local_score), trial));
        }
        let mut candidates = Vec::new();
        if let Some((_, trial)) = local_candidates.into_iter().max_by(|left, right| {
            left.0.total_cmp(&right.0).then_with(|| {
                right
                    .1
                    .partial_cmp(&left.1)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        }) {
            if let Some((candidate, _)) = problem.structure(context, &trial)
                && let Ok(score) =
                    problem
                        .scorer
                        .score_fixed_region(region, &candidate, problem.targets)
            {
                evaluations = evaluations.saturating_add(1);
                candidates.push((score_value(&score), score, trial));
            }
        }

        let mut selected = candidates.into_iter().max_by(|left, right| {
            left.0.total_cmp(&right.0).then_with(|| {
                right
                    .2
                    .partial_cmp(&left.2)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        });

        // If neither side of a linkage improves independently, test the
        // chemically connected parent/child saddle.  Only direct children
        // are paired, so the prefix remains frozen and no distal residue can
        // leapfrog an unresolved intermediate.
        if !exhaustive
            && selected
                .as_ref()
                .is_none_or(|candidate| candidate.0 <= score_value(&current_score) + 1.0e-4)
        {
            let child_indices = problem
                .branches
                .iter()
                .enumerate()
                .filter(|(_, child)| child.parent_residue == branch.child_residue)
                .map(|(index, _)| index)
                .collect::<Vec<_>>();
            let saddle_offsets = [-30.0_f64, 0.0, 30.0];
            for child_index in child_indices {
                let child_dimension = problem.angle_dimensions + child_index;
                if child_dimension >= point.len() {
                    continue;
                }
                let mut quick_saddles = Vec::new();
                for parent_offset in saddle_offsets {
                    for child_offset in saddle_offsets {
                        let mut trial = point.clone();
                        trial[dimension] = wrap_degrees(trial[dimension] + parent_offset);
                        trial[child_dimension] =
                            wrap_degrees(trial[child_dimension] + child_offset);
                        let Some((structure, _)) = problem.structure(context, &trial) else {
                            continue;
                        };
                        if max_vdw_overlap_pair(&structure, vdw).0 > 1.20 {
                            continue;
                        }
                        quick_saddles.push((quick_score(&structure), trial));
                    }
                }
                quick_saddles.sort_by(|left, right| {
                    right.0.total_cmp(&left.0).then_with(|| {
                        left.1
                            .partial_cmp(&right.1)
                            .unwrap_or(std::cmp::Ordering::Equal)
                    })
                });
                for (_, trial) in quick_saddles.into_iter().take(1) {
                    let Some((structure, _)) = problem.structure(context, &trial) else {
                        continue;
                    };
                    let Ok(score) =
                        problem
                            .scorer
                            .score_fixed_region(region, &structure, problem.targets)
                    else {
                        continue;
                    };
                    evaluations = evaluations.saturating_add(1);
                    let candidate = (score_value(&score), score, trial);
                    if selected
                        .as_ref()
                        .is_none_or(|current| candidate.0 > current.0)
                    {
                        selected = Some(candidate);
                    }
                }
            }
        }

        if let Some((value, score, trial)) = selected
            && value > score_value(&current_score) + 1.0e-4
            && score.heldout_likelihood_gain + 1.0e-4 >= current_score.heldout_likelihood_gain
        {
            point = trial;
            current_score = score;
            if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some()
                || std::env::var_os("REGLYCO_DENSITY_DEBUG_FINAL").is_some()
            {
                eprintln!(
                    "adaptive-frozen-frontier: branch={} child={} score={:.4} ll={:.3} heldout={:.3}",
                    branch.label,
                    branch.child_residue,
                    value,
                    current_score.likelihood_gain,
                    current_score.heldout_likelihood_gain
                );
            }
        }
    }
    (point, evaluations)
}

/// Fit each unresolved linkage on the retained complete tree in topological
/// order.  This is intentionally a final, bounded rescue pass rather than a
/// second global search: the root/core and every accepted prefix stay fixed
/// while one child residue explores its complete chemically valid torsion
/// circle.  The residual scorer sees only the current child and its connected
/// prefix, which prevents a strong distal blob from winning by itself.
fn adaptive_progressive_branch_refine(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    initial: &[f64],
    vdw: &VdwClashContext,
) -> (Vec<f64>, usize) {
    if problem.deadline_reached() {
        return (initial.to_vec(), 0);
    }
    let mut point = initial.to_vec();
    let mut evaluations = 0usize;
    let core = problem
        .targets
        .iter()
        .flat_map(|target| target.glycan_residues.iter().take(3).cloned())
        .collect::<BTreeSet<_>>();

    for arm in connected_arm_definitions(problem.branches).iter().take(2) {
        if problem.deadline_reached() {
            break;
        }
        let arm_set = arm.residues.iter().cloned().collect::<BTreeSet<_>>();
        let mut groups = arm
            .residues
            .iter()
            .filter_map(|child| {
                let mut axes = problem
                    .branches
                    .iter()
                    .enumerate()
                    .filter(|(_, branch)| {
                        branch.child_residue == *child && arm_set.contains(&branch.child_residue)
                    })
                    .map(|(index, _)| index)
                    .collect::<Vec<_>>();
                axes.sort_by(|left, right| {
                    problem.branches[*left]
                        .label
                        .cmp(&problem.branches[*right].label)
                        .then_with(|| left.cmp(right))
                });
                (!axes.is_empty()).then_some((child.clone(), axes))
            })
            .collect::<Vec<_>>();
        groups.sort_by(|left, right| {
            branch_depth(problem.branches, left.1[0])
                .cmp(&branch_depth(problem.branches, right.1[0]))
                .then_with(|| left.0.cmp(&right.0))
        });

        let mut placed = core.clone();
        placed.insert(arm.parent_residue.clone());
        for (child, axes) in groups {
            if problem.deadline_reached() {
                break;
            }
            // This is the pose at the moment the frontier reaches `child`.
            // Later proposals may move the child linkage, but a weakly
            // supported branch should remain close to this connected
            // GlycoShape/native pose rather than jumping to a distal blob.
            let child_anchor = point.clone();
            // Keep a residue-local, candidate-independent ROI for the whole
            // frontier step.  The region is built once from the current
            // connected pose and reused for every torsion proposal, so a
            // rotated ring cannot move its mask along with itself.  A generous
            // halo is intentional: distal rings can be several angstroms from
            // the native GlycoShape orientation while still being chemically
            // reachable from the fitted parent.
            //
            // Score each frontier step against the complete connected subtree
            // of this arm already constructed plus the new child (Phase 6:
            // "score the complete currently constructed subtree").  A distal
            // residue with weak *isolated* ring density is still credited when
            // its placement completes a connected arm that together explains
            // the density well.  The same-arm residues are kept out of the
            // fixed `placed_target` so they are scored as the moving subtree,
            // not subtracted as if they were immovable background.
            // Measured on cached 5KZC this whole-arm scoring is currently
            // inert (bit-for-bit identical final RMSD/CC): the alpha-1,3 arm
            // B:4/B:5 departure is an ambiguous-density representative, not an
            // isolated-residual-gate failure, so no single-arm scoring change
            // moves it.  The change is retained as the architecturally-correct
            // Phase 6 behavior and is non-regressing.
            let subtree = arm
                .residues
                .iter()
                .filter(|residue| placed.contains(*residue) || **residue == child)
                .cloned()
                .collect::<BTreeSet<_>>();
            let child_target = problem
                .targets
                .iter()
                .map(|target| DensityTarget {
                    site: target.site.clone(),
                    glycan_residues: target
                        .glycan_residues
                        .iter()
                        .filter(|residue| subtree.contains(*residue))
                        .cloned()
                        .collect(),
                })
                .filter(|target| !target.glycan_residues.is_empty())
                .collect::<Vec<_>>();
            // A multi-residue subtree target must never be empty for a target
            // that owns the child (e.g. a target list that placed the child in
            // a different site).  Fall back to the lone child ring so the
            // step stays well-defined rather than scoring an empty field.
            let child_target = if child_target.is_empty() {
                problem
                    .targets
                    .iter()
                    .map(|target| DensityTarget {
                        site: target.site.clone(),
                        glycan_residues: vec![child.clone()],
                    })
                    .collect::<Vec<_>>()
            } else {
                child_target
            };
            let placed_target = problem
                .targets
                .iter()
                .map(|target| DensityTarget {
                    site: target.site.clone(),
                    glycan_residues: target
                        .glycan_residues
                        .iter()
                        .filter(|residue| placed.contains(*residue) && !subtree.contains(*residue))
                        .cloned()
                        .collect(),
                })
                .filter(|target| !target.glycan_residues.is_empty())
                .collect::<Vec<_>>();
            let child_region_holder =
                problem
                    .structure(context, &point)
                    .and_then(|(structure, _)| {
                        problem
                            .scorer
                            .fixed_region(&[&structure], &child_target, 8.0)
                            .ok()
                    });
            let baseline = progressive_branch_value(
                problem,
                context,
                &point,
                &placed,
                &child,
                &axes,
                vdw,
                &child_target,
                &placed_target,
                child_region_holder.as_ref(),
                &child_anchor,
            );
            evaluations = evaluations.saturating_add(1);
            // Normal Adaptive uses the bounded five-point trust region.  The
            // previous `is_none()` condition accidentally enabled the
            // 13^n exhaustive lattice by default, so a seven-residue site
            // spent minutes in repeated fixed-ROI rescoring before terminal
            // refinement.  Exhaustion remains an explicit diagnostic mode.
            let exhaustive = std::env::var_os("REGLYCO_ADAPTIVE_EXHAUSTIVE").is_some()
                || std::env::var_os("REGLYCO_ADAPTIVE_EXACT_FRONTIER").is_some();
            let coarse_values = axes
                .iter()
                .map(|axis| {
                    let dimension = problem.angle_dimensions + *axis;
                    let offsets = if exhaustive {
                        if problem.branches[*axis].label.contains("[omega]") {
                            (-3..=3).map(|step| 60.0 * step as f64).collect::<Vec<_>>()
                        } else {
                            (-6..=6).map(|step| 30.0 * step as f64).collect::<Vec<_>>()
                        }
                    } else {
                        // The old 13^n/7^n Cartesian grid dominated adaptive
                        // runtime and repeatedly evaluated disconnected
                        // poses. A five-point trust region covers the full
                        // chemically common basin; the correlated native
                        // proposal and subtree stage handle the rare saddle
                        // outside it. Keep the exhaustive grid available for
                        // scientific diagnostics.
                        vec![-120.0, -60.0, 0.0, 60.0, 120.0]
                    };
                    offsets
                        .into_iter()
                        .map(|offset| wrap_degrees(point[dimension] + offset))
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>();
            let mut trials = Vec::<Vec<f64>>::new();
            fn expand_progressive_trials(
                point: &[f64],
                axes: &[usize],
                values: &[Vec<f64>],
                angle_dimensions: usize,
                depth: usize,
                current: &mut Vec<f64>,
                output: &mut Vec<Vec<f64>>,
            ) {
                if depth == axes.len() {
                    output.push(current.clone());
                    return;
                }
                let dimension = angle_dimensions + axes[depth];
                for value in &values[depth] {
                    current[dimension] = *value;
                    expand_progressive_trials(
                        point,
                        axes,
                        values,
                        angle_dimensions,
                        depth + 1,
                        current,
                        output,
                    );
                }
                current[dimension] = point[dimension];
            }
            expand_progressive_trials(
                &point,
                &axes,
                &coarse_values,
                problem.angle_dimensions,
                0,
                &mut point.clone(),
                &mut trials,
            );
            let mut ranked = trials
                .par_iter()
                .filter(|_| !problem.deadline_reached())
                .filter_map(|trial| {
                    let value = progressive_branch_value(
                        problem,
                        context,
                        trial,
                        &placed,
                        &child,
                        &axes,
                        vdw,
                        &child_target,
                        &placed_target,
                        child_region_holder.as_ref(),
                        &child_anchor,
                    );
                    value.is_finite().then(|| (value, trial.clone()))
                })
                .collect::<Vec<_>>();
            evaluations = evaluations.saturating_add(trials.len());
            if problem.deadline_reached() {
                break;
            }
            ranked.sort_by(|left, right| {
                right.0.total_cmp(&left.0).then_with(|| {
                    left.1
                        .partial_cmp(&right.1)
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
            });
            let mut candidate = ranked.first().cloned();
            // The atom-local residual is a capture surrogate and can rank a
            // nearby protein blob above the connected ring supported by the
            // fixed child ROI.  Re-score a finite deterministic shortlist on
            // that same ROI before committing the frontier step.  Root
            // residues get the complete coarse set because a wrong root
            // orientation propagates through every descendant; terminal
            // residues only need the leading local hypotheses.
            if let Some(region) = child_region_holder.as_ref() {
                let exact_limit = if problem
                    .branches
                    .iter()
                    .any(|branch| branch.parent_residue == child)
                {
                    ranked.len()
                } else {
                    ranked.len().min(10)
                };
                let mut exact_candidates = ranked
                    .iter()
                    .take(exact_limit)
                    .filter_map(|(_, trial)| {
                        let structure = problem.structure(context, trial)?.0;
                        let score = problem
                            .scorer
                            .score_fixed_region_residual(
                                region,
                                &structure,
                                &placed_target,
                                &child_target,
                            )
                            .ok()?;
                        let value = score.likelihood_gain
                            + 0.5 * score.heldout_likelihood_gain
                            + 0.2 * score.protein_adjusted_correlation;
                        Some((value, trial.clone()))
                    })
                    .collect::<Vec<_>>();
                evaluations = evaluations.saturating_add(exact_candidates.len());
                exact_candidates.sort_by(|left, right| {
                    right.0.total_cmp(&left.0).then_with(|| {
                        left.1
                            .partial_cmp(&right.1)
                            .unwrap_or(std::cmp::Ordering::Equal)
                    })
                });
                if let Some((_, exact_trial)) = exact_candidates.into_iter().next() {
                    let value = progressive_branch_value(
                        problem,
                        context,
                        &exact_trial,
                        &placed,
                        &child,
                        &axes,
                        vdw,
                        &child_target,
                        &placed_target,
                        child_region_holder.as_ref(),
                        &child_anchor,
                    );
                    candidate = value.is_finite().then_some((value, exact_trial));
                }
            }
            // A small fine grid around the best coarse mode catches the
            // deposited-like orientation without opening a continuous global
            // optimizer.  Keep it to the leading three hypotheses so runtime
            // is bounded even for linkages with an exocyclic omega variable.
            for (_, seed) in ranked.into_iter().take(3) {
                if problem.deadline_reached() {
                    break;
                }
                let fine_values = axes
                    .iter()
                    .map(|axis| {
                        let dimension = problem.angle_dimensions + *axis;
                        [-10.0, 0.0, 10.0]
                            .into_iter()
                            .map(|delta| wrap_degrees(seed[dimension] + delta))
                            .collect::<Vec<_>>()
                    })
                    .collect::<Vec<_>>();
                let mut fine_trials = Vec::new();
                expand_progressive_trials(
                    &seed,
                    &axes,
                    &fine_values,
                    problem.angle_dimensions,
                    0,
                    &mut seed.clone(),
                    &mut fine_trials,
                );
                let mut fine = fine_trials
                    .par_iter()
                    .filter(|_| !problem.deadline_reached())
                    .filter_map(|trial| {
                        let value = progressive_branch_value(
                            problem,
                            context,
                            trial,
                            &placed,
                            &child,
                            &axes,
                            vdw,
                            &child_target,
                            &placed_target,
                            child_region_holder.as_ref(),
                            &child_anchor,
                        );
                        value.is_finite().then(|| (value, trial.clone()))
                    })
                    .collect::<Vec<_>>();
                evaluations = evaluations.saturating_add(fine_trials.len());
                if problem.deadline_reached() {
                    break;
                }
                fine.sort_by(|left, right| right.0.total_cmp(&left.0));
                if let Some(best_fine) = fine.into_iter().next()
                    && candidate
                        .as_ref()
                        .is_none_or(|current| best_fine.0 > current.0)
                {
                    candidate = Some(best_fine);
                }
            }
            // The coarse/fine grid locates a basin, but a pyranose ring can
            // still have the right centre with its plane rotated several
            // degrees away from the map.  Refine only this child linkage on
            // the fixed child ROI before comparing it with the parent pose.
            // Older branches are untouched, so a distal correction cannot
            // propagate an error back through an already accepted prefix.
            if let Some((_, seed)) = candidate.take() {
                if problem.deadline_reached() {
                    break;
                }
                // The exact child ROI remains the acceptance authority below,
                // but using it for every trust-region trial makes one branch
                // dominate the entire site runtime.  Normal Adaptive uses
                // the cached atom-local residual for the proposal refinement;
                // the explicit exhaustive switch retains the exact gradient
                // path for scientific diagnostics.
                let (refined, local_evaluations) = if exhaustive_frontier_search() {
                    progressive_fixed_torsion_refine(
                        problem,
                        context,
                        &seed,
                        &axes,
                        &child_target,
                        &placed_target,
                        child_region_holder.as_ref(),
                        vdw,
                        &placed,
                        &child,
                        &child_anchor,
                    )
                } else {
                    (seed, 0)
                };
                evaluations = evaluations.saturating_add(local_evaluations);
                let refined_value = progressive_branch_value(
                    problem,
                    context,
                    &refined,
                    &placed,
                    &child,
                    &axes,
                    vdw,
                    &child_target,
                    &placed_target,
                    child_region_holder.as_ref(),
                    &child_anchor,
                );
                candidate = refined_value
                    .is_finite()
                    .then_some((refined_value, refined));
            }
            let selected_value = candidate.as_ref().map(|entry| entry.0);
            let baseline_residual = child_region_holder.as_ref().and_then(|region| {
                problem
                    .scorer
                    .score_fixed_region_residual(
                        region,
                        &problem.structure(context, &child_anchor)?.0,
                        &placed_target,
                        &child_target,
                    )
                    .ok()
            });
            let selected_residual = candidate.as_ref().and_then(|(_, trial)| {
                let structure = problem.structure(context, trial)?.0;
                child_region_holder.as_ref().and_then(|region| {
                    problem
                        .scorer
                        .score_fixed_region_residual(
                            region,
                            &structure,
                            &placed_target,
                            &child_target,
                        )
                        .ok()
                })
            });
            let residual_gate = baseline_residual
                .as_ref()
                .zip(selected_residual.as_ref())
                .is_none_or(|(before, after)| {
                    let before_value = before.likelihood_gain
                        + 0.5 * before.heldout_likelihood_gain
                        + 0.2 * before.protein_adjusted_correlation;
                    let after_value = after.likelihood_gain
                        + 0.5 * after.heldout_likelihood_gain
                        + 0.2 * after.protein_adjusted_correlation;
                    let max_move = axes
                        .iter()
                        .map(|axis| {
                            let dimension = problem.angle_dimensions + *axis;
                            child_anchor
                                .get(dimension)
                                .zip(
                                    candidate
                                        .as_ref()
                                        .and_then(|(_, trial)| trial.get(dimension)),
                                )
                                .map(|(from, to)| angular_delta_degrees(*from, *to))
                                .unwrap_or(0.0)
                        })
                        .max_by(f64::total_cmp)
                        .unwrap_or(0.0);
                    let has_unfitted_descendants = problem
                        .branches
                        .iter()
                        .any(|branch| branch.parent_residue == child);
                    // A branch root can require a broad correlated rotation
                    // before its descendants become visible.  The old 12°
                    // cap rejected exactly that move on 5GSQ C:4, freezing
                    // the native wrong alpha-1,6 arm.  Keep the connected
                    // residual/ring gates below as the anti-blob guard, but
                    // allow a chemically reachable root to cross its full
                    // local torsion basin.  Terminal children remain bounded
                    // more tightly because they have no prefix to rescue.
                    let allowed_move = if has_unfitted_descendants { 90.0 } else { 60.0 };
                    // A large move is accepted only when the prefix-subtracted
                    // ring evidence is genuinely strong.  This blocks the
                    // characteristic 1-6 failure where B7/B8 jump to a
                    // nearby blob with a slightly better atom-local score.
                    after_value > before_value + 1.0e-4
                        && (max_move <= allowed_move
                            || after.protein_adjusted_correlation >= 0.30
                            || after.likelihood_gain >= 10.0)
                });
            let accepted = candidate.as_ref().is_some_and(|(value, trial)| {
                *value > baseline + 1.0e-4
                    && residual_gate
                    && progressive_child_is_connected(problem, context, trial, &child, &axes)
            });
            if accepted {
                if let Some((_, trial)) = candidate {
                    point = trial;
                }
            }
            if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some()
                || std::env::var_os("REGLYCO_DENSITY_DEBUG_FINAL").is_some()
            {
                eprintln!(
                    "adaptive-progressive: arm={} child={} baseline={baseline:.5} selected={selected_value:?} accepted={} residual_base={:?} residual_selected={:?}",
                    arm.label, child, accepted, baseline_residual, selected_residual
                );
            }
            placed.insert(child);
        }
    }
    (point, evaluations)
}

#[derive(Debug, Clone)]
struct TerminalLinkagePoseBasis {
    residue: ResidueId,
    pivot: AtomId,
    moving: Vec<AtomId>,
    axes: [Vec3; 3],
}

#[derive(Debug, Clone)]
struct TerminalRingPoseBasis {
    residue: ResidueId,
    pivot: AtomId,
    moving: Vec<AtomId>,
    axes: [Vec3; 3],
}

fn terminal_linkage_pose_basis(
    structure: &Structure,
    branches: &[BranchRotation],
    residue: &ResidueId,
) -> Option<TerminalLinkagePoseBasis> {
    let branch = branches
        .iter()
        .filter(|branch| branch.child_residue == *residue && branch.label.contains("[phi]"))
        .min_by(|left, right| left.label.cmp(&right.label))?;
    let pivot = branch.axis.1;
    let child = branch.axis.0;
    let origin = structure.atom(pivot)?.position;
    let child_position = structure.atom(child)?.position;
    let direction = normalize_vec(sub_vec(child_position, origin));
    let seed = if direction.x.abs() < 0.8 {
        Vec3 {
            x: 1.0,
            y: 0.0,
            z: 0.0,
        }
    } else {
        Vec3 {
            x: 0.0,
            y: 1.0,
            z: 0.0,
        }
    };
    let first = normalize_vec(cross_vec(direction, seed));
    let second = normalize_vec(cross_vec(direction, first));
    let moving = branch
        .moving
        .iter()
        .filter_map(|atom| structure.atom(*atom).map(|value| (value, *atom)))
        .filter(|(atom, _)| !atom.element.eq_ignore_ascii_case("H"))
        .map(|(_, atom)| atom)
        .collect::<Vec<_>>();
    (!moving.is_empty()).then_some(TerminalLinkagePoseBasis {
        residue: residue.clone(),
        pivot,
        moving,
        // The linkage direction is the third axis. Rotating around it is the
        // full glycosidic phi degree of freedom; the two perpendicular axes
        // move C1 on the parent-acceptor sphere without changing any internal
        // residue bond or angle.
        axes: [first, second, direction],
    })
}

fn apply_terminal_linkage_pose(
    structure: &Structure,
    basis: &TerminalLinkagePoseBasis,
    angles_degrees: [f64; 3],
) -> Option<Structure> {
    let origin = structure.atom(basis.pivot)?.position;
    let mut candidate = structure.clone();
    for (axis, angle) in basis.axes.iter().zip(angles_degrees) {
        rotate_structure_atoms(
            &mut candidate,
            &basis.moving,
            origin,
            *axis,
            angle.to_radians(),
        )
        .ok()?;
    }
    Some(candidate)
}

fn apply_terminal_torsion_pose(
    structure: &Structure,
    branches: &[&BranchRotation],
    angles_degrees: &[f64],
) -> Option<Structure> {
    if branches.len() != angles_degrees.len() {
        return None;
    }
    let mut candidate = structure.clone();
    for (branch, angle) in branches.iter().zip(angles_degrees) {
        rotate_branch(&mut candidate, branch, angle.to_radians()).ok()?;
    }
    Some(candidate)
}

/// Search rigid poses of complete connected subtrees on one fixed global
/// likelihood.  Rotating only a residue is tempting, but it moves a parent
/// acceptor away from its child and makes an unrelated density peak look
/// attractive.  A subtree rotation keeps every internal bond and every
/// descendant linkage intact while preserving the incoming C1 bond.
fn adaptive_connected_subtree_pose_refine(
    problem: &DensitySwarmProblem<'_>,
    initial: &Structure,
    vdw: &VdwClashContext,
    targets: &[DensityTarget],
) -> (Structure, usize) {
    if problem.deadline_reached() {
        return (initial.clone(), 0);
    }
    let Some(region) = problem.fixed_region else {
        return (initial.clone(), 0);
    };
    let residues = targets
        .iter()
        .flat_map(|target| target.glycan_residues.iter().cloned())
        .collect::<BTreeSet<_>>();
    if residues.is_empty() {
        return (initial.clone(), 0);
    }
    let mut children = BTreeMap::<ResidueId, Vec<ResidueId>>::new();
    for branch in problem.branches {
        children
            .entry(branch.parent_residue.clone())
            .or_default()
            .push(branch.child_residue.clone());
    }
    for values in children.values_mut() {
        values.sort();
        values.dedup();
    }
    let mut ordered = residues.iter().cloned().collect::<Vec<_>>();
    ordered.sort_by(|left, right| {
        let left_depth = residue_subtree_depth(left, &children);
        let right_depth = residue_subtree_depth(right, &children);
        right_depth.cmp(&left_depth).then_with(|| left.cmp(right))
    });

    let score_value = |score: &DensityFixedScore| {
        // Keep all three terms on comparable scales.  The held-out term is
        // deliberately substantial: a pose must explain independent voxels,
        // not just overfit the training fold of a broad ring mask.
        score.likelihood_gain
            + 1.0 * score.heldout_likelihood_gain
            + 20.0 * score.protein_adjusted_correlation
    };
    let mut structure = initial.clone();
    let mut current = match problem
        .scorer
        .score_fixed_region(region, &structure, targets)
        .ok()
    {
        Some(score) => score,
        None => return (structure, 1),
    };
    let mut evaluations = 1usize;
    let exhaustive = std::env::var_os("REGLYCO_ADAPTIVE_EXHAUSTIVE").is_some();
    for residue in ordered {
        if problem.deadline_reached() {
            break;
        }
        let Some(pivot) = structure.find_atom(&residue, "C1") else {
            continue;
        };
        let Some(c2) = structure.find_atom(&residue, "C2") else {
            continue;
        };
        let Some(o5) = structure.find_atom(&residue, "O5") else {
            continue;
        };
        let Some(origin) = structure.atom(pivot).map(|atom| atom.position) else {
            continue;
        };
        let Some(c2_position) = structure.atom(c2).map(|atom| atom.position) else {
            continue;
        };
        let Some(o5_position) = structure.atom(o5).map(|atom| atom.position) else {
            continue;
        };
        let first = normalize_vec(sub_vec(c2_position, origin));
        let normal = normalize_vec(cross_vec(
            sub_vec(c2_position, origin),
            sub_vec(o5_position, origin),
        ));
        let third = normalize_vec(cross_vec(normal, first));
        let axes = [normal, first, third];
        let mut subtree = BTreeSet::from([residue.clone()]);
        let mut pending = vec![residue.clone()];
        while let Some(parent) = pending.pop() {
            for child in children.get(&parent).into_iter().flatten() {
                if subtree.insert(child.clone()) {
                    pending.push(child.clone());
                }
            }
        }
        let moving = structure
            .atoms()
            .into_iter()
            .filter(|atom| {
                subtree.contains(&atom.residue)
                    && atom.id != pivot
                    && !atom.element.eq_ignore_ascii_case("H")
            })
            .map(|atom| atom.id)
            .collect::<Vec<_>>();
        if moving.is_empty() {
            continue;
        }
        let coarse_yaw = if exhaustive {
            (0..12).map(|index| index as f64 * 30.0).collect::<Vec<_>>()
        } else {
            vec![-90.0, 0.0, 90.0]
        };
        let coarse_tilt = if exhaustive {
            vec![-60.0, -30.0, 0.0, 30.0, 60.0]
        } else {
            vec![0.0]
        };
        let mut proposals = Vec::<[f64; 3]>::new();
        for yaw in &coarse_yaw {
            for tilt_a in &coarse_tilt {
                for tilt_b in &coarse_tilt {
                    proposals.push([*yaw, *tilt_a, *tilt_b]);
                }
            }
        }
        let base = structure.clone();
        let evaluated = proposals
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|angles| {
                let mut candidate = base.clone();
                for (axis, angle) in axes.iter().zip(angles) {
                    rotate_structure_atoms(
                        &mut candidate,
                        &moving,
                        origin,
                        *axis,
                        angle.to_radians(),
                    )
                    .ok()?;
                }
                if max_vdw_overlap_pair(&candidate, vdw).0 > 1.20
                    || !density_pose_has_no_serious_clash(&candidate, targets)
                {
                    return None;
                }
                let score = problem
                    .scorer
                    .score_fixed_region(region, &candidate, targets)
                    .ok()?;
                Some((score_value(&score), *angles, score, candidate))
            })
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(proposals.len());
        if problem.deadline_reached() {
            break;
        }
        let Some(mut best) = evaluated.into_iter().max_by(|left, right| {
            left.0.total_cmp(&right.0).then_with(|| {
                right
                    .1
                    .partial_cmp(&left.1)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        }) else {
            continue;
        };
        // Refine only the leading basin. This captures a few degrees of ring
        // frame error without multiplying full-tree evaluations by every
        // coarse hypothesis.
        let fine_offsets = if exhaustive {
            vec![-12.0, 0.0, 12.0]
        } else {
            vec![-8.0, 0.0, 8.0]
        };
        let mut fine = Vec::new();
        for da in &fine_offsets {
            if problem.deadline_reached() {
                break;
            }
            for db in &fine_offsets {
                if problem.deadline_reached() {
                    break;
                }
                for dc in &fine_offsets {
                    if problem.deadline_reached() {
                        break;
                    }
                    let angles = [best.1[0] + *da, best.1[1] + *db, best.1[2] + *dc];
                    let mut candidate = base.clone();
                    let mut valid = true;
                    for (axis, angle) in axes.iter().zip(angles) {
                        if rotate_structure_atoms(
                            &mut candidate,
                            &moving,
                            origin,
                            *axis,
                            angle.to_radians(),
                        )
                        .is_err()
                        {
                            valid = false;
                            break;
                        }
                    }
                    if !valid {
                        continue;
                    }
                    if max_vdw_overlap_pair(&candidate, vdw).0 > 1.20
                        || !density_pose_has_no_serious_clash(&candidate, targets)
                    {
                        continue;
                    }
                    let Some(score) = problem
                        .scorer
                        .score_fixed_region(region, &candidate, targets)
                        .ok()
                    else {
                        continue;
                    };
                    fine.push((score_value(&score), angles, score, candidate));
                }
            }
        }
        evaluations = evaluations.saturating_add(fine.len());
        if problem.deadline_reached() {
            break;
        }
        if let Some(candidate) = fine.into_iter().max_by(|left, right| {
            left.0.total_cmp(&right.0).then_with(|| {
                right
                    .1
                    .partial_cmp(&left.1)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        }) {
            if candidate.0 > best.0 {
                best = candidate;
            }
        }
        let improves = best.0 > score_value(&current) + 1.0e-4;
        let heldout_preserved =
            best.2.heldout_likelihood_gain + 1.0e-4 >= current.heldout_likelihood_gain;
        if improves && heldout_preserved {
            structure = best.3;
            current = best.2;
            if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some()
                || std::env::var_os("REGLYCO_DENSITY_DEBUG_FINAL").is_some()
            {
                eprintln!(
                    "adaptive-subtree-pose: residue={} subtree={} score={:.4} ll={:.3} heldout={:.3} angles={:?}",
                    residue,
                    subtree.len(),
                    best.0,
                    current.likelihood_gain,
                    current.heldout_likelihood_gain,
                    best.1
                );
            }
        }
    }
    (structure, evaluations)
}

/// Cheap terminal residue registration for normal Adaptive mode.
///
/// The legacy terminal routines score every rigid pose with the complete
/// fixed-region likelihood.  That made a five-residue Man9 frontier take
/// minutes even though only a handful of poses were competitive.  Generate
/// the same chemically connected torsion/ring proposals, rank them with the
/// atom-local residual sampler, and exact-score only the four best proposals
/// per leaf.  Parents and already accepted siblings remain frozen.
fn adaptive_terminal_frontier_refine(
    problem: &DensitySwarmProblem<'_>,
    initial: &Structure,
    vdw: &VdwClashContext,
    targets: &[DensityTarget],
) -> (Structure, usize) {
    if problem.deadline_reached() {
        return (initial.clone(), 0);
    }
    let Some(region) = problem.fixed_region else {
        return (initial.clone(), 0);
    };
    let residues = targets
        .iter()
        .flat_map(|target| target.glycan_residues.iter().cloned())
        .collect::<BTreeSet<_>>();
    let parents = problem
        .branches
        .iter()
        .map(|branch| branch.parent_residue.clone())
        .collect::<BTreeSet<_>>();
    let mut leaves = residues
        .into_iter()
        .filter(|residue| !parents.contains(residue))
        .collect::<Vec<_>>();
    leaves.sort();
    let mut structure = initial.clone();
    let Some(mut current_score) = problem
        .scorer
        .score_fixed_region(region, &structure, targets)
        .ok()
    else {
        return (structure, 1);
    };
    let score_value = |score: &DensityFixedScore| {
        score.likelihood_gain
            + 0.75 * score.heldout_likelihood_gain
            + 20.0 * score.protein_adjusted_correlation
    };
    let exhaustive = std::env::var_os("REGLYCO_ADAPTIVE_TERMINAL_EXHAUSTIVE").is_some();
    let torsion_values = if exhaustive {
        vec![-180.0, -120.0, -60.0, 0.0, 60.0, 120.0]
    } else {
        vec![-120.0, -60.0, 0.0, 60.0, 120.0]
    };
    let mut evaluations = 1usize;

    fn expand_angles(
        values: &[f64],
        depth: usize,
        current: &mut Vec<f64>,
        output: &mut Vec<Vec<f64>>,
    ) {
        if depth == current.capacity() {
            output.push(current.clone());
            return;
        }
        for value in values {
            current.push(*value);
            expand_angles(values, depth + 1, current, output);
            current.pop();
        }
    }

    for residue in leaves {
        if problem.deadline_reached() {
            break;
        }
        let mut terminal_branches = problem
            .branches
            .iter()
            .filter(|branch| branch.child_residue == residue)
            .collect::<Vec<_>>();
        terminal_branches.sort_by(|left, right| left.label.cmp(&right.label));
        if terminal_branches.is_empty() {
            continue;
        }
        let child_atoms = structure
            .atoms()
            .into_iter()
            .filter(|atom| atom.residue == residue && !atom.element.eq_ignore_ascii_case("H"))
            .map(|atom| atom.id)
            .collect::<BTreeSet<_>>();
        if child_atoms.is_empty() {
            continue;
        }
        let child_targets = targets
            .iter()
            .map(|target| DensityTarget {
                site: target.site.clone(),
                glycan_residues: vec![residue.clone()],
            })
            .collect::<Vec<_>>();
        let child_region = {
            let refs = vec![&structure];
            problem.scorer.fixed_region(&refs, &child_targets, 8.0).ok()
        };
        let mut proposals = Vec::<(f64, Structure)>::new();
        let mut angles = Vec::new();
        let mut seed = Vec::with_capacity(terminal_branches.len());
        expand_angles(&torsion_values, 0, &mut seed, &mut angles);
        // `Vec::capacity` is the fixed recursion depth.  The helper above
        // intentionally uses it instead of a second branch-count argument so
        // malformed linkage metadata cannot produce an unbounded recursion.
        angles.retain(|candidate| candidate.len() == terminal_branches.len());
        for candidate_angles in angles {
            if problem.deadline_reached() {
                break;
            }
            let Some(candidate) =
                apply_terminal_torsion_pose(&structure, &terminal_branches, &candidate_angles)
            else {
                continue;
            };
            if max_vdw_overlap_pair(&candidate, vdw).0 > 1.20 {
                continue;
            }
            let quick = problem
                .scorer
                .atom_local_evidence(&candidate, &child_atoms)
                .map(|evidence| evidence.score)
                .unwrap_or(f64::NEG_INFINITY);
            proposals.push((quick, candidate));
        }
        if let Some(basis) = terminal_ring_pose_basis(&structure, &residue) {
            let ring_yaw = [-90.0_f64, -45.0, 0.0, 45.0, 90.0];
            let ring_tilt = [-30.0_f64, 0.0, 30.0];
            for yaw in ring_yaw {
                if problem.deadline_reached() {
                    break;
                }
                for tilt_a in ring_tilt {
                    if problem.deadline_reached() {
                        break;
                    }
                    for tilt_b in ring_tilt {
                        if problem.deadline_reached() {
                            break;
                        }
                        let Some(candidate) =
                            apply_terminal_ring_pose(&structure, &basis, [yaw, tilt_a, tilt_b])
                        else {
                            continue;
                        };
                        if max_vdw_overlap_pair(&candidate, vdw).0 > 1.20 {
                            continue;
                        }
                        let quick = problem
                            .scorer
                            .atom_local_evidence(&candidate, &child_atoms)
                            .map(|evidence| evidence.score)
                            .unwrap_or(f64::NEG_INFINITY);
                        proposals.push((quick, candidate));
                    }
                }
            }
        }
        proposals.sort_by(|left, right| {
            right
                .0
                .total_cmp(&left.0)
                .then_with(|| left.1.atoms().len().cmp(&right.1.atoms().len()))
        });
        proposals.truncate(if exhaustive { 12 } else { 4 });
        let mut local_candidates = Vec::new();
        for (_, candidate) in proposals {
            if problem.deadline_reached() {
                break;
            }
            let Some(score) = child_region.as_ref().and_then(|local_region| {
                problem
                    .scorer
                    .score_fixed_region(local_region, &candidate, &child_targets)
                    .ok()
            }) else {
                continue;
            };
            evaluations = evaluations.saturating_add(1);
            local_candidates.push((score_value(&score), candidate));
        }
        let mut best_candidate = None;
        if let Some((_, candidate)) = local_candidates.into_iter().max_by(|left, right| {
            left.0
                .total_cmp(&right.0)
                .then_with(|| left.1.atoms().len().cmp(&right.1.atoms().len()))
        }) {
            let Ok(score) = problem
                .scorer
                .score_fixed_region(region, &candidate, targets)
            else {
                continue;
            };
            evaluations = evaluations.saturating_add(1);
            best_candidate = Some((score_value(&score), score, candidate));
        }
        if let Some((value, score, candidate)) = best_candidate
            && value > score_value(&current_score) + 1.0e-4
            && score.heldout_likelihood_gain + 1.0e-4 >= current_score.heldout_likelihood_gain
            && density_pose_has_no_serious_clash(&candidate, targets)
        {
            structure = candidate;
            current_score = score;
            if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some()
                || std::env::var_os("REGLYCO_DENSITY_DEBUG_FINAL").is_some()
            {
                eprintln!(
                    "adaptive-terminal-frontier: residue={} score={:.4} ll={:.3} heldout={:.3}",
                    residue,
                    value,
                    current_score.likelihood_gain,
                    current_score.heldout_likelihood_gain
                );
            }
        }
    }
    (structure, evaluations)
}

fn residue_subtree_depth(
    residue: &ResidueId,
    children: &BTreeMap<ResidueId, Vec<ResidueId>>,
) -> usize {
    children
        .get(residue)
        .map(|values| {
            values
                .iter()
                .map(|child| residue_subtree_depth(child, children))
                .max()
                .unwrap_or(0)
                + 1
        })
        .unwrap_or(0)
}

/// Search the complete local torsion manifold of each terminal residue.  The
/// frontier pass already samples native ensemble modes, but its 5-degree
/// coordinate polish can remain in the wrong basin when a distal arm has a
/// strong, sharp ring signal.  This stage keeps the exact glycosidic axes and
/// therefore preserves linkage chemistry while allowing every terminal
/// phi/psi (and parent omega, for an alpha-1,6 child) to cross the circular
/// boundary.  A sharper fixed-width scorer chooses poses; the calibrated
/// complete-tree gate still decides whether any pose is retained.
fn adaptive_terminal_torsion_refine(
    problem: &DensitySwarmProblem<'_>,
    initial: &Structure,
    vdw: &VdwClashContext,
    targets: &[DensityTarget],
) -> (Structure, usize) {
    if problem.deadline_reached() {
        return (initial.clone(), 0);
    }
    let residues = targets
        .iter()
        .flat_map(|target| target.glycan_residues.iter().cloned())
        .collect::<BTreeSet<_>>();
    let parents = problem
        .branches
        .iter()
        .map(|branch| branch.parent_residue.clone())
        .collect::<BTreeSet<_>>();
    let mut leaves = residues
        .into_iter()
        .filter(|residue| !parents.contains(residue))
        .collect::<Vec<_>>();
    leaves.sort();
    let mut structure = initial.clone();
    let mut evaluations = 0usize;
    let sharp_scorer = {
        let mut options = problem.scorer.options;
        let sigma = options.sigma_angstrom.unwrap_or(1.0);
        options.sigma_angstrom = Some((0.55 * sigma).clamp(0.45, 0.60));
        problem
            .scorer
            .clone()
            .with_options(options)
            .ok()
            .and_then(|scorer| {
                scorer
                    .attach_protein_background(initial, targets)
                    .ok()
                    .map(|_| scorer)
            })
    };
    let scorer = sharp_scorer.as_ref().unwrap_or(problem.scorer);

    for residue in leaves {
        if problem.deadline_reached() {
            break;
        }
        let mut terminal_branches = problem
            .branches
            .iter()
            .filter(|branch| branch.child_residue == residue)
            .cloned()
            .collect::<Vec<_>>();
        terminal_branches.sort_by_key(|branch| {
            let label = &branch.label;
            if label.contains("[omega]") {
                0
            } else if label.contains("[psi]") {
                1
            } else {
                2
            }
        });
        if terminal_branches.is_empty() {
            continue;
        }
        let branches = terminal_branches.iter().collect::<Vec<_>>();
        let child_target = targets
            .iter()
            .map(|target| DensityTarget {
                site: target.site.clone(),
                glycan_residues: vec![residue.clone()],
            })
            .collect::<Vec<_>>();
        let prefix_targets = terminal_ancestor_targets(problem, &residue, targets);
        let Some(region) = scorer.fixed_region(&[&structure], &child_target, 8.0).ok() else {
            continue;
        };
        let score_angles = |angles: &[f64], base: &Structure| {
            let candidate = apply_terminal_torsion_pose(base, &branches, angles)?;
            let (value, score, candidate) = terminal_ring_structure_value(
                problem,
                scorer,
                &region,
                &candidate,
                &prefix_targets,
                &child_target,
                vdw,
                angles.iter().map(|angle| angle.abs()).sum::<f64>() * 0.0002 / 360.0,
            )?;
            Some((value, angles.to_vec(), score, candidate))
        };
        let baseline = score_angles(&vec![0.0; branches.len()], &structure);
        evaluations = evaluations.saturating_add(1);
        let Some((baseline_value, _, baseline_score, _)) = baseline else {
            continue;
        };
        let exhaustive = std::env::var_os("REGLYCO_ADAPTIVE_EXHAUSTIVE").is_some();
        let coarse_values = branches
            .iter()
            .map(|branch| {
                if exhaustive {
                    (0..6).map(|index| index as f64 * 60.0).collect::<Vec<_>>()
                } else if branch.label.contains("[omega]") {
                    vec![-60.0, 0.0, 60.0]
                } else {
                    vec![-90.0, 0.0, 90.0]
                }
            })
            .collect::<Vec<_>>();
        let coarse_angles = coarse_values
            .into_iter()
            .fold(vec![Vec::new()], |acc, values| {
                acc.into_iter()
                    .flat_map(|prefix| {
                        values.iter().map(move |value| {
                            let mut next = prefix.clone();
                            next.push(*value);
                            next
                        })
                    })
                    .collect::<Vec<_>>()
            });
        let mut ranked = coarse_angles
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|angles| score_angles(angles, &structure))
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(coarse_angles.len());
        ranked.sort_by(|left, right| right.0.total_cmp(&left.0));
        let seeds = ranked
            .iter()
            .take(if exhaustive { 4 } else { 2 })
            .map(|(_, angles, _, _)| angles.clone())
            .collect::<Vec<_>>();
        let fine_angles = seeds
            .iter()
            .flat_map(|seed| {
                let offsets = [-10.0, 0.0, 10.0];
                (0..3usize.pow(branches.len() as u32)).map(move |mut code| {
                    let mut angles = seed.clone();
                    for angle in &mut angles {
                        *angle += offsets[code % 3];
                        code /= 3;
                    }
                    angles
                })
            })
            .collect::<Vec<_>>();
        let mut fine = fine_angles
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|angles| score_angles(angles, &structure))
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(fine_angles.len());
        ranked.append(&mut fine);
        // A local grid can miss a correlated arm saddle even when the exact
        // GlycoShape mode is present in the ensemble.  Screen every native
        // terminal torsion vector at the retained placement as a cheap,
        // deterministic proposal set.  The mode is scored against the same
        // fixed child ROI as the grid and still has to pass the held-out,
        // chemistry, and complete-tree gates below; it is therefore a prior
        // proposal, never a restraint or a deposited-coordinate input.
        let native_limit = if exhaustive { usize::MAX } else { 16 };
        let native_angles = problem
            .template_positions
            .iter()
            .take(native_limit)
            .collect::<Vec<_>>()
            .into_par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|(_, positions)| {
                let mut template = structure.clone();
                template
                    .set_atom_positions(positions.iter().map(|(atom, position)| (*atom, *position)))
                    .ok()?;
                let angles = branches
                    .iter()
                    .map(|branch| {
                        let current = branch_torsion_degrees(&structure, branch)?;
                        let native = branch_torsion_degrees(&template, branch)?;
                        Some(wrap_degrees(native - current))
                    })
                    .collect::<Option<Vec<_>>>()?;
                Some(angles)
            })
            .collect::<Vec<_>>();
        let mut native = native_angles
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|angles| score_angles(angles, &structure))
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(native_angles.len());
        ranked.append(&mut native);
        ranked.sort_by(|left, right| right.0.total_cmp(&left.0));
        if (std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some()
            || std::env::var_os("REGLYCO_DENSITY_DEBUG_FINAL").is_some())
            && (residue.number == 9 || residue.number == 8)
        {
            for (value, angles, score, candidate) in ranked.iter().take(8) {
                eprintln!(
                    "adaptive-terminal-hypothesis: residue={} value={value:.5} angles={angles:?} likelihood={:.4} heldout={:.4} cc={:.4} overlap={:.4}",
                    residue,
                    score.likelihood_gain,
                    score.heldout_likelihood_gain,
                    score.correlation,
                    max_vdw_overlap_pair(candidate, vdw).0,
                );
            }
        }
        if let Some((value, angles, candidate_score, candidate)) = ranked.into_iter().next()
            && value > baseline_value + 1.0e-4
        {
            let candidate_clean = density_pose_vdw_clean(&candidate, vdw)
                && max_vdw_overlap_pair(&candidate, vdw).0 <= 1.20;
            // A terminal proposal must beat the local model-complexity noise,
            // not merely improve one correlated voxel block by a few
            // thousandths.  The fixed ROI is the same for every proposal;
            // require a held-out likelihood gain and a meaningful primary
            // gain over the unchanged terminal residue before opening a new
            // torsion basin. This prevents the observed B8 regression where
            // a tiny local CC increase selected a worse connected pose.
            let local_primary_gain =
                candidate_score.likelihood_gain - baseline_score.likelihood_gain;
            let local_heldout_gain =
                candidate_score.heldout_likelihood_gain - baseline_score.heldout_likelihood_gain;
            let local_bic_gain = candidate_score.bic_gain - baseline_score.bic_gain;
            let evidence_gate =
                local_primary_gain >= 0.50 && local_heldout_gain >= 0.05 && local_bic_gain >= 0.25;
            let global_gate = problem.fixed_region.map_or(true, |global_region| {
                let current = problem
                    .scorer
                    .score_fixed_region(global_region, &structure, targets)
                    .ok();
                let proposed = problem
                    .scorer
                    .score_fixed_region(global_region, &candidate, targets)
                    .ok();
                proposed
                    .as_ref()
                    .zip(current.as_ref())
                    .is_none_or(|(proposed, current)| {
                        proposed.heldout_likelihood_gain + 1.0e-4 >= current.heldout_likelihood_gain
                            && (proposed.likelihood_gain > current.likelihood_gain + 1.0e-6
                                || proposed.correlation > current.correlation + 1.0e-6)
                    })
            });
            if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some()
                || std::env::var_os("REGLYCO_DENSITY_DEBUG_FINAL").is_some()
            {
                eprintln!(
                    "adaptive-terminal-torsion-local: residue={} baseline={baseline_value:.5} selected={value:.5} angles={angles:?} chemistry_ok={} evidence_gate={} primary_delta={local_primary_gain:.4} heldout_delta={local_heldout_gain:.4} bic_delta={local_bic_gain:.4} global_gate={}",
                    residue, candidate_clean, evidence_gate, global_gate
                );
            }
            if candidate_clean && evidence_gate && global_gate {
                structure = candidate;
            }
        }
    }
    (structure, evaluations)
}

/// Build a local rigid-pose frame for a terminal pyranose ring.  The first
/// axis is the ring normal, followed by two in-plane axes.  The anomeric C1
/// is kept as the pivot so the parent--child bond and the fitted attachment
/// do not move during this stage.
fn terminal_ring_pose_basis(
    structure: &Structure,
    residue: &ResidueId,
) -> Option<TerminalRingPoseBasis> {
    let pivot = structure.find_atom(residue, "C1")?;
    let c2 = structure.find_atom(residue, "C2")?;
    let o5 = structure.find_atom(residue, "O5")?;
    let pivot_position = structure.atom(pivot)?.position;
    let c2_vector = sub_vec(structure.atom(c2)?.position, pivot_position);
    let o5_vector = sub_vec(structure.atom(o5)?.position, pivot_position);
    let normal_raw = cross_vec(c2_vector, o5_vector);
    if dot_vec(normal_raw, normal_raw) <= 1.0e-10 {
        return None;
    }
    let normal = normalize_vec(normal_raw);
    let in_plane = normalize_vec(c2_vector);
    let second = normalize_vec(cross_vec(normal, in_plane));
    let moving = structure
        .atoms()
        .into_iter()
        .filter(|atom| {
            atom.residue == *residue && atom.id != pivot && !atom.element.eq_ignore_ascii_case("H")
        })
        .map(|atom| atom.id)
        .collect::<Vec<_>>();
    (!moving.is_empty()).then_some(TerminalRingPoseBasis {
        residue: residue.clone(),
        pivot,
        moving,
        axes: [normal, in_plane, second],
    })
}

fn rotate_structure_atoms(
    structure: &mut Structure,
    atoms: &[AtomId],
    origin: Vec3,
    axis_vector: Vec3,
    radians: f64,
) -> Result<()> {
    let axis_length = dot_vec(axis_vector, axis_vector).sqrt();
    if axis_length <= 1.0e-12 {
        return Err(RefineError::DensityNoPose);
    }
    let axis = scale_vec(axis_vector, 1.0 / axis_length);
    let (sine, cosine) = radians.sin_cos();
    let updates = atoms
        .iter()
        .filter_map(|atom| structure.atom(*atom).map(|value| (*atom, value.position)))
        .map(|(atom, point)| {
            let relative = sub_vec(point, origin);
            let cross = cross_vec(axis, relative);
            let parallel = dot_vec(axis, relative);
            let rotated = add_vec(
                add_vec(scale_vec(relative, cosine), scale_vec(cross, sine)),
                scale_vec(axis, parallel * (1.0 - cosine)),
            );
            (atom, add_vec(origin, rotated))
        })
        .collect::<Vec<_>>();
    structure.set_atom_positions(updates)?;
    Ok(())
}

fn apply_terminal_ring_pose(
    structure: &Structure,
    basis: &TerminalRingPoseBasis,
    angles_degrees: [f64; 3],
) -> Option<Structure> {
    let origin = structure.atom(basis.pivot)?.position;
    let mut candidate = structure.clone();
    for (axis, angle) in basis.axes.iter().zip(angles_degrees) {
        rotate_structure_atoms(
            &mut candidate,
            &basis.moving,
            origin,
            *axis,
            angle.to_radians(),
        )
        .ok()?;
    }
    Some(candidate)
}

fn transplant_terminal_ring_template(
    structure: &Structure,
    template: &BTreeMap<AtomId, Vec3>,
    basis: &TerminalRingPoseBasis,
) -> Option<Structure> {
    let current_pivot = structure.atom(basis.pivot)?.position;
    let template_pivot = *template.get(&basis.pivot)?;
    let updates = basis
        .moving
        .iter()
        .filter_map(|atom| {
            let template_position = *template.get(atom)?;
            Some((
                *atom,
                add_vec(current_pivot, sub_vec(template_position, template_pivot)),
            ))
        })
        .collect::<Vec<_>>();
    if updates.len() != basis.moving.len() {
        return None;
    }
    let mut candidate = structure.clone();
    candidate.set_atom_positions(updates).ok()?;
    Some(candidate)
}

/// Targets that belong to the already connected ancestor prefix of a
/// terminal residue. Distal siblings are deliberately left in the observed
/// residual: subtracting their current, potentially unsupported geometry
/// makes a child appear to be explained by a wrong blob and was the source of
/// the alpha-1,6 residue-skipping failure.
fn terminal_ancestor_targets(
    problem: &DensitySwarmProblem<'_>,
    residue: &ResidueId,
    targets: &[DensityTarget],
) -> Vec<DensityTarget> {
    let mut ancestors = BTreeSet::from([residue.clone()]);
    let mut current = residue.clone();
    while let Some(parent) = problem
        .branches
        .iter()
        .find(|branch| branch.child_residue == current)
        .map(|branch| branch.parent_residue.clone())
    {
        if !ancestors.insert(parent.clone()) {
            break;
        }
        current = parent;
    }
    targets
        .iter()
        .map(|target| DensityTarget {
            site: target.site.clone(),
            glycan_residues: target
                .glycan_residues
                .iter()
                .filter(|candidate| ancestors.contains(*candidate) && **candidate != *residue)
                .cloned()
                .collect(),
        })
        .filter(|target| !target.glycan_residues.is_empty())
        .collect()
}

fn terminal_ring_structure_value(
    problem: &DensitySwarmProblem<'_>,
    scorer: &DensityScorer,
    region: &DensityFixedRegion,
    structure: &Structure,
    prefix_targets: &[DensityTarget],
    child_target: &[DensityTarget],
    vdw: &VdwClashContext,
    pose_penalty: f64,
) -> Option<(f64, DensityFixedScore, Structure)> {
    if max_vdw_overlap_pair(structure, vdw).0 > 1.20 {
        return None;
    }
    let residual_score = scorer
        .score_fixed_region_residual(region, structure, prefix_targets, child_target)
        .ok()?;
    // Keep a complete-tree fixed-ROI term alongside the prefix-subtracted
    // child residual.  The residual is the right frontier signal, but a
    // deeply correlated arm can temporarily look worse after subtraction
    // even while its complete calculated field explains more of the fixed
    // observed map.  The union uses exactly the same voxels for every pose;
    // it cannot follow a candidate-specific mask.
    // The complete-tree term must include siblings and unsupported tails; it
    // is intentionally independent from the ancestor-only residual above.
    let full_score = scorer
        .score_fixed_region(region, structure, problem.targets)
        .ok()?;
    let scale = (residual_score.voxel_count as f64).sqrt().max(1.0);
    let full_scale = (full_score.voxel_count as f64).sqrt().max(1.0);
    let value = residual_score.likelihood_gain / scale
        + 0.50 * residual_score.heldout_likelihood_gain / scale
        + 1.50 * residual_score.protein_adjusted_correlation
        + 0.35 * full_score.likelihood_gain / full_scale
        + 0.15 * full_score.heldout_likelihood_gain / full_scale
        + 0.35 * full_score.protein_adjusted_correlation
        - pose_penalty;
    value
        .is_finite()
        .then_some((value, full_score, structure.clone()))
}

/// Refine the orientation of each terminal child about its parent acceptor.
/// The normal torsion variables rotate around fixed chemical axes and can
/// miss a displaced C1 when the originating ring frame is poor. This bounded
/// two-angle linkage correction keeps the parent atom and bond length fixed,
/// then lets the ring-frame stage correct the remaining internal pose.
fn adaptive_terminal_linkage_pose_refine(
    problem: &DensitySwarmProblem<'_>,
    initial: &Structure,
    vdw: &VdwClashContext,
    targets: &[DensityTarget],
) -> (Structure, usize) {
    if problem.deadline_reached() {
        return (initial.clone(), 0);
    }
    let residues = targets
        .iter()
        .flat_map(|target| target.glycan_residues.iter().cloned())
        .collect::<BTreeSet<_>>();
    let parents = problem
        .branches
        .iter()
        .map(|branch| branch.parent_residue.clone())
        .collect::<BTreeSet<_>>();
    let mut leaves = residues
        .into_iter()
        .filter(|residue| !parents.contains(residue))
        .collect::<Vec<_>>();
    leaves.sort();
    let mut structure = initial.clone();
    let mut evaluations = 0usize;
    // Linkage placement is a local pose-registration problem.  The broad
    // sigma used by adaptive capture intentionally smooths over basin noise,
    // but it also makes two ring orientations look almost equivalent.  Use a
    // fixed, sharper kernel only to choose among poses in this local stage;
    // the calibrated adaptive scorer remains the authority for complete-tree
    // acceptance below.
    let sharp_scorer = {
        let mut options = problem.scorer.options;
        let sigma = options.sigma_angstrom.unwrap_or(1.0);
        options.sigma_angstrom = Some((0.70 * sigma).clamp(0.55, 0.85));
        problem
            .scorer
            .clone()
            .with_options(options)
            .ok()
            .and_then(|scorer| {
                scorer
                    .attach_protein_background(initial, targets)
                    .ok()
                    .map(|_| scorer)
            })
    };
    let local_scorer = sharp_scorer.as_ref().unwrap_or(problem.scorer);

    for residue in leaves {
        if problem.deadline_reached() {
            break;
        }
        let Some(basis) = terminal_linkage_pose_basis(&structure, problem.branches, &residue)
        else {
            continue;
        };
        let child_target = targets
            .iter()
            .map(|target| DensityTarget {
                site: target.site.clone(),
                glycan_residues: vec![residue.clone()],
            })
            .collect::<Vec<_>>();
        let prefix_targets = terminal_ancestor_targets(problem, &residue, targets);
        let Some(region) = local_scorer
            .fixed_region(&[&structure], &child_target, 8.0)
            .ok()
        else {
            continue;
        };
        let score_angles = |angles: [f64; 3], base: &Structure| {
            let candidate = apply_terminal_linkage_pose(base, &basis, angles)?;
            terminal_ring_structure_value(
                problem,
                local_scorer,
                &region,
                &candidate,
                &prefix_targets,
                &child_target,
                vdw,
                angles.iter().map(|angle| angle.abs()).sum::<f64>() * 0.0005 / 360.0,
            )
            .map(|(value, score, candidate)| (value, angles, score, candidate))
        };
        let baseline = score_angles([0.0; 3], &structure);
        evaluations = evaluations.saturating_add(1);
        let Some((baseline_value, _, _, _)) = baseline else {
            continue;
        };
        // A terminal ring can be correctly placed in the map while its
        // parent-relative direction is on the opposite side of the starting
        // basin.  The old +/-60 degree cube could never reach that pose (the
        // 5KZC alpha-1,6 tip needs roughly an 80 degree change).  Enumerate a
        // complete, deterministic +/-180 degree linkage manifold at the
        // inexpensive local-ROI stage; the fine trust region then removes the
        // remaining grid error.  This rotates the chemically connected
        // residue as a rigid body, so it cannot create the ring-angle defect
        // of the ring-only stage.
        let exhaustive = std::env::var_os("REGLYCO_ADAPTIVE_EXHAUSTIVE").is_some();
        let coarse_angles = if exhaustive {
            (-6..=6)
                .flat_map(|first| {
                    (-2..=2).flat_map(move |second| {
                        (-2..=2).map(move |third| {
                            [
                                first as f64 * 30.0,
                                second as f64 * 30.0,
                                third as f64 * 30.0,
                            ]
                        })
                    })
                })
                .collect::<Vec<_>>()
        } else {
            [-1.0_f64, 0.0, 1.0]
                .into_iter()
                .flat_map(|first| {
                    [-1.0_f64, 0.0, 1.0].into_iter().flat_map(move |second| {
                        [-1.0_f64, 0.0, 1.0]
                            .into_iter()
                            .map(move |third| [first * 90.0, second * 60.0, third * 60.0])
                    })
                })
                .collect::<Vec<_>>()
        };
        let mut ranked = coarse_angles
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|angles| score_angles(*angles, &structure))
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(coarse_angles.len());
        ranked.sort_by(|left, right| right.0.total_cmp(&left.0));
        let seeds = ranked
            .iter()
            .take(if exhaustive { 4 } else { 2 })
            .map(|(_, angles, _, _)| *angles)
            .collect::<Vec<_>>();
        let fine_angles = seeds
            .iter()
            .flat_map(|seed| {
                [-12.0, 0.0, 12.0].into_iter().flat_map(move |first| {
                    [-12.0, 0.0, 12.0].into_iter().flat_map(move |second| {
                        [-12.0, 0.0, 12.0]
                            .into_iter()
                            .map(move |third| [seed[0] + first, seed[1] + second, seed[2] + third])
                    })
                })
            })
            .collect::<Vec<_>>();
        let mut fine = fine_angles
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|angles| score_angles(*angles, &structure))
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(fine_angles.len());
        ranked.append(&mut fine);
        ranked.sort_by(|left, right| right.0.total_cmp(&left.0));
        if let Some((value, angles, _, candidate)) = ranked.into_iter().next()
            && value > baseline_value + 1.0e-4
        {
            structure = candidate;
            if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some()
                || std::env::var_os("REGLYCO_DENSITY_DEBUG_FINAL").is_some()
            {
                eprintln!(
                    "adaptive-linkage-pose-local: residue={} baseline={baseline_value:.5} selected={value:.5} angles={angles:?}",
                    basis.residue
                );
            }
        }
    }
    (structure, evaluations)
}

fn terminal_ring_pose_value(
    problem: &DensitySwarmProblem<'_>,
    scorer: &DensityScorer,
    region: &DensityFixedRegion,
    structure: &Structure,
    prefix_targets: &[DensityTarget],
    child_target: &[DensityTarget],
    angles_degrees: [f64; 3],
    basis: &TerminalRingPoseBasis,
    vdw: &VdwClashContext,
) -> Option<(f64, DensityFixedScore, Structure)> {
    let candidate = apply_terminal_ring_pose(structure, basis, angles_degrees)?;
    // The fixed residual likelihood is primary.  Held-out gain and the
    // protein-adjusted correlation stabilize the choice when a terminal ring
    // has only a few resolved peaks; the small pose prior keeps exactly
    // equivalent orientations deterministic without overpowering density.
    let pose_penalty = angles_degrees
        .iter()
        .map(|angle| angle.abs() / 360.0)
        .sum::<f64>()
        * 0.001;
    terminal_ring_structure_value(
        problem,
        scorer,
        region,
        &candidate,
        prefix_targets,
        child_target,
        vdw,
        pose_penalty,
    )
}

/// Refine terminal residue ring frames after progressive linkage fitting.
/// The search is deliberately finite (300 coarse poses plus a small local
/// trust region per leaf) and uses a child-only fixed ROI with the accepted
/// prefix subtracted.  This gives the optimizer a degree of freedom that
/// glycosidic torsions cannot provide, while keeping the already-fitted parent
/// and the protein fixed.
fn adaptive_terminal_ring_pose_refine(
    problem: &DensitySwarmProblem<'_>,
    initial: &Structure,
    vdw: &VdwClashContext,
    targets: &[DensityTarget],
) -> (Structure, usize) {
    if problem.deadline_reached() {
        return (initial.clone(), 0);
    }
    let residues = targets
        .iter()
        .flat_map(|target| target.glycan_residues.iter().cloned())
        .collect::<BTreeSet<_>>();
    let parents = problem
        .branches
        .iter()
        .map(|branch| branch.parent_residue.clone())
        .collect::<BTreeSet<_>>();
    let mut leaves = residues
        .into_iter()
        .filter(|residue| !parents.contains(residue))
        .collect::<Vec<_>>();
    leaves.sort();
    let mut structure = initial.clone();
    let mut evaluations = 0usize;
    // Terminal ring orientation is resolved by a sharper, fixed-width field
    // than the broad adaptive capture map.  Keep the calibrated primary
    // scorer as the final acceptance authority; this sharp scorer only
    // chooses among local ring poses and cannot alter scale or mask geometry.
    let sharp_scorer = {
        let mut options = problem.scorer.options;
        let sigma = options.sigma_angstrom.unwrap_or(1.0);
        options.sigma_angstrom = Some((0.70 * sigma).clamp(0.55, 0.85));
        problem
            .scorer
            .clone()
            .with_options(options)
            .ok()
            .and_then(|scorer| {
                scorer
                    .attach_protein_background(initial, targets)
                    .ok()
                    .map(|_| scorer)
            })
    };
    let scorer = sharp_scorer.as_ref().unwrap_or(problem.scorer);

    for residue in leaves {
        if problem.deadline_reached() {
            break;
        }
        let Some(basis) = terminal_ring_pose_basis(&structure, &residue) else {
            continue;
        };
        let child_target = targets
            .iter()
            .map(|target| DensityTarget {
                site: target.site.clone(),
                glycan_residues: vec![residue.clone()],
            })
            .collect::<Vec<_>>();
        let prefix_targets = terminal_ancestor_targets(problem, &residue, targets);
        let Some(region) = scorer.fixed_region(&[&structure], &child_target, 8.0).ok() else {
            continue;
        };
        let baseline = terminal_ring_pose_value(
            problem,
            scorer,
            &region,
            &structure,
            &prefix_targets,
            &child_target,
            [0.0; 3],
            &basis,
            vdw,
        );
        evaluations = evaluations.saturating_add(1);
        let Some((baseline_value, _, _)) = baseline else {
            continue;
        };

        let exhaustive = std::env::var_os("REGLYCO_ADAPTIVE_EXHAUSTIVE").is_some();
        let coarse_angles = if exhaustive {
            (0..12)
                .flat_map(|yaw| {
                    (-2..=2).flat_map(move |tilt_a| {
                        (-2..=2).map(move |tilt_b| {
                            [
                                yaw as f64 * 30.0,
                                tilt_a as f64 * 30.0,
                                tilt_b as f64 * 30.0,
                            ]
                        })
                    })
                })
                .collect::<Vec<_>>()
        } else {
            [-1.0_f64, 0.0, 1.0]
                .into_iter()
                .flat_map(|yaw| {
                    [-1.0_f64, 0.0, 1.0].into_iter().flat_map(move |tilt_a| {
                        [-1.0_f64, 0.0, 1.0]
                            .into_iter()
                            .map(move |tilt_b| [yaw * 90.0, tilt_a * 30.0, tilt_b * 30.0])
                    })
                })
                .collect::<Vec<_>>()
        };
        let mut coarse = coarse_angles
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|angles| {
                terminal_ring_pose_value(
                    problem,
                    scorer,
                    &region,
                    &structure,
                    &prefix_targets,
                    &child_target,
                    *angles,
                    &basis,
                    vdw,
                )
                .map(|(value, score, candidate)| (value, *angles, score, candidate))
            })
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(coarse_angles.len());
        coarse.sort_by(|left, right| {
            right.0.total_cmp(&left.0).then_with(|| {
                left.1
                    .partial_cmp(&right.1)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        });
        let mut refined = coarse.into_iter().take(4).collect::<Vec<_>>();
        let seeds = refined
            .iter()
            .take(if exhaustive { 4 } else { 2 })
            .map(|(_, angles, _, _)| *angles)
            .collect::<Vec<_>>();
        let fine_angles = seeds
            .iter()
            .flat_map(|seed| {
                [-12.0, 0.0, 12.0].into_iter().flat_map(move |a| {
                    [-12.0, 0.0, 12.0].into_iter().flat_map(move |b| {
                        [-12.0, 0.0, 12.0].into_iter().map(move |c| {
                            [
                                wrap_degrees(seed[0] + a),
                                (seed[1] + b).clamp(-90.0, 90.0),
                                (seed[2] + c).clamp(-90.0, 90.0),
                            ]
                        })
                    })
                })
            })
            .collect::<Vec<_>>();
        let mut fine = fine_angles
            .par_iter()
            .filter(|_| !problem.deadline_reached())
            .filter_map(|angles| {
                terminal_ring_pose_value(
                    problem,
                    scorer,
                    &region,
                    &structure,
                    &prefix_targets,
                    &child_target,
                    *angles,
                    &basis,
                    vdw,
                )
                .map(|(value, score, candidate)| (value, *angles, score, candidate))
            })
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(fine_angles.len());
        refined.append(&mut fine);
        // Preserve internal ring-pucker and substituent variants from the
        // supplied GlycoShape ensemble.  The rigid pose search above changes
        // orientation but cannot change a template's chair geometry.  A
        // template is transplanted at the already-fitted C1 and scored in the
        // same residual ROI; only the best few survive the local comparison.
        let native_limit = if exhaustive { usize::MAX } else { 64 };
        let native_templates = problem
            .template_positions
            .iter()
            .take(native_limit)
            .collect::<Vec<_>>()
            .into_par_iter()
            .filter_map(|(_, template)| {
                let candidate = transplant_terminal_ring_template(&structure, template, &basis)?;
                terminal_ring_structure_value(
                    problem,
                    scorer,
                    &region,
                    &candidate,
                    &prefix_targets,
                    &child_target,
                    vdw,
                    0.0005,
                )
                .map(|(value, score, candidate)| (value, [0.0; 3], score, candidate))
            })
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(problem.template_positions.len());
        refined.extend(native_templates);
        refined.sort_by(|left, right| right.0.total_cmp(&left.0));
        if let Some((value, angles, _, candidate)) = refined.into_iter().next()
            && value > baseline_value + 1.0e-4
        {
            structure = candidate;
            if std::env::var_os("REGLYCO_DENSITY_DEBUG").is_some()
                || std::env::var_os("REGLYCO_DENSITY_DEBUG_FINAL").is_some()
            {
                eprintln!(
                    "adaptive-ring-pose-local: residue={} baseline={baseline_value:.5} selected={value:.5} angles={angles:?}",
                    basis.residue
                );
            }
        }
    }
    (structure, evaluations)
}

/// Reopen only the attachment and conserved three-residue core on a small
/// fixed ROI before growing distal arms.  The broad search already supplies
/// the correct basin; this pass removes the systematic sub-angstrom core
/// orientation error that otherwise gets multiplied by every downstream
/// glycosidic linkage.  Distal branch offsets are kept intact and the final
/// complete-tree fixed-ROI gate decides whether the core move survives.
fn adaptive_core_fixed_refine(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    initial: &[f64],
    vdw: &VdwClashContext,
) -> (Vec<f64>, usize) {
    if problem.deadline_reached() {
        return (initial.to_vec(), 0);
    }
    let core_residues = problem
        .targets
        .iter()
        .flat_map(|target| target.glycan_residues.iter().take(3).cloned())
        .collect::<BTreeSet<_>>();
    if core_residues.is_empty() {
        return (initial.to_vec(), 0);
    }
    let core_targets = problem
        .targets
        .iter()
        .map(|target| DensityTarget {
            site: target.site.clone(),
            glycan_residues: target
                .glycan_residues
                .iter()
                .filter(|residue| core_residues.contains(*residue))
                .cloned()
                .collect(),
        })
        .filter(|target| !target.glycan_residues.is_empty())
        .collect::<Vec<_>>();
    let Some((structure, _)) = problem.structure(context, initial) else {
        return (initial.to_vec(), 0);
    };
    let region = problem
        .scorer
        .fixed_region(&[&structure], &core_targets, 8.0)
        .ok();
    let Some(region) = region.as_ref() else {
        return (initial.to_vec(), 0);
    };
    let mut active = (0..problem.angle_dimensions).collect::<Vec<_>>();
    active.extend(
        problem
            .branches
            .iter()
            .enumerate()
            .filter(|(_, branch)| core_residues.contains(&branch.child_residue))
            .map(|(index, _)| problem.angle_dimensions + index),
    );
    active.sort_unstable();
    active.dedup();
    let value = |position: &[f64]| {
        problem
            .structure(context, position)
            .and_then(|(candidate, _)| {
                if max_vdw_overlap_pair(&candidate, vdw).0 > 1.20 {
                    return None;
                }
                problem
                    .scorer
                    .score_fixed_region(region, &candidate, &core_targets)
                    .ok()
                    .map(|score| {
                        let scale = (score.voxel_count as f64).sqrt().max(1.0);
                        0.10 * score.likelihood_gain / scale
                            + 0.05 * score.heldout_likelihood_gain / scale
                            + 0.25 * score.protein_adjusted_correlation
                    })
            })
            .unwrap_or(f64::NEG_INFINITY)
    };
    let mut point = initial.to_vec();
    let mut best = value(&point);
    let mut evaluations = 1usize;
    let mut stagnant = 0usize;
    for step in [8.0, 4.0, 2.0, 1.0, 0.5] {
        if problem.deadline_reached() {
            break;
        }
        let mut trials = Vec::with_capacity(active.len() * 2);
        for dimension in &active {
            for direction in [-1.0, 1.0] {
                let mut trial = point.clone();
                trial[*dimension] = if *dimension < problem.angle_dimensions {
                    wrap_degrees(trial[*dimension] + direction * step)
                } else {
                    wrap_degrees(trial[*dimension] + direction * step)
                };
                trials.push(trial);
            }
        }
        let mut scored = trials
            .into_par_iter()
            .filter(|_| !problem.deadline_reached())
            .map(|trial| (value(&trial), trial))
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(scored.len());
        scored.sort_by(|left, right| {
            right.0.total_cmp(&left.0).then_with(|| {
                left.1
                    .partial_cmp(&right.1)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
        });
        if let Some((candidate, trial)) = scored.into_iter().next()
            && candidate > best + 1.0e-5
        {
            best = candidate;
            point = trial;
            stagnant = 0;
        } else {
            stagnant += 1;
            if stagnant >= 3 {
                break;
            }
        }
    }
    (point, evaluations)
}

fn progressive_branch_value(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    position: &[f64],
    placed: &BTreeSet<ResidueId>,
    child: &ResidueId,
    axes: &[usize],
    vdw: &VdwClashContext,
    child_target: &[DensityTarget],
    placed_target: &[DensityTarget],
    child_region: Option<&DensityFixedRegion>,
    anchor: &[f64],
) -> f64 {
    let Some((structure, _)) = problem.structure(context, position) else {
        return f64::NEG_INFINITY;
    };
    if max_vdw_overlap_pair(&structure, vdw).0 > 1.20 {
        return f64::NEG_INFINITY;
    }
    let local = problem
        .frontier_atoms
        .map(|cache| frontier_local_objective(problem, &structure, cache, placed, child, axes))
        .unwrap_or(f64::NEG_INFINITY);
    let child_support = frontier_child_support(problem, &structure, child, axes);
    // A weak/partly absent linkage corridor must not make the whole residue
    // unsearchable.  In that case retain the candidate-independent child
    // residual as the proposal signal; the sequential topology order still
    // prevents it from skipping its parent or an intervening residue.
    let child_residual = problem
        .scorer
        .fast_evidence(&structure, child_target)
        .map(|evidence| evidence.score)
        .unwrap_or(f64::NEG_INFINITY);
    let residual = if local.is_finite() {
        local
    } else {
        child_residual
    };
    if !residual.is_finite() {
        return residual;
    }
    let full = problem
        .scorer
        .fast_evidence(&structure, problem.targets)
        .map(|evidence| evidence.score)
        .unwrap_or(0.0);
    // The fixed residue ROI is the decisive term for ring orientation.  The
    // moving-mask residual remains useful for a weak/partial map, but by
    // itself it can reward a ring whose centre is near density while its
    // plane is rotated into an unrelated peak.  Profiled fixed-region
    // likelihood and held-out gain measure the complete child field against
    // the same observed voxels for every proposal.
    let fixed_signal = child_region
        .and_then(|region| {
            problem
                .scorer
                .score_fixed_region_residual(region, &structure, placed_target, child_target)
                .ok()
        })
        .map(|score| {
            let scale = (score.voxel_count as f64).sqrt().max(1.0);
            0.04 * score.likelihood_gain / scale
                + 0.02 * score.heldout_likelihood_gain / scale
                + 0.15 * score.protein_adjusted_correlation
        })
        .unwrap_or(0.0);
    // Penalize only large moves away from the accepted frontier pose.  This
    // is intentionally a soft GlycoShape prior: a clearly supported ring can
    // still move far, while a weak branch cannot leap one or two torsional
    // wells merely because an unrelated positive peak is nearby.
    let prior_penalty = axes
        .iter()
        .map(|axis| {
            let dimension = problem.angle_dimensions + *axis;
            let delta = anchor
                .get(dimension)
                .zip(position.get(dimension))
                .map(|(from, to)| angular_delta_degrees(*from, *to))
                .unwrap_or(0.0);
            let excess = (delta - 25.0).max(0.0);
            0.0015 * excess + 0.000005 * excess * excess
        })
        .sum::<f64>();
    residual + fixed_signal + 0.20 * child_support.0 + 0.08 * child_support.1 + 0.02 * full
        - prior_penalty
}

/// Locally refine one residue's linkage against a fixed ROI.  This is a
/// deliberately small trust-region search, not a second global optimizer:
/// only the linkage axes that create `child` are allowed to move, and every
/// accepted step is evaluated on the same child voxels.  The analytic map
/// gradient supplies a correlated proposal while the exact fixed-region
/// score remains the acceptance authority.
fn progressive_fixed_torsion_refine(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    initial: &[f64],
    axes: &[usize],
    child_target: &[DensityTarget],
    placed_target: &[DensityTarget],
    region: Option<&DensityFixedRegion>,
    vdw: &VdwClashContext,
    placed: &BTreeSet<ResidueId>,
    child: &ResidueId,
    anchor: &[f64],
) -> (Vec<f64>, usize) {
    let Some(region) = region else {
        return (initial.to_vec(), 0);
    };
    let Some((_initial_structure, _)) = problem.structure(context, initial) else {
        return (initial.to_vec(), 0);
    };
    let mut point = initial.to_vec();
    let mut best_value = progressive_branch_value(
        problem,
        context,
        initial,
        placed,
        child,
        axes,
        vdw,
        child_target,
        placed_target,
        Some(region),
        anchor,
    );
    let mut evaluations = 1usize;
    let mut stagnant = 0usize;
    for step in [20.0, 10.0, 5.0, 2.0, 1.0, 0.5] {
        let Some((structure, _)) = problem.structure(context, &point) else {
            break;
        };
        let gradients = problem
            .scorer
            .score_fixed_region_with_gradients(region, &structure, child_target)
            .ok()
            .map(|evidence| {
                axes.iter()
                    .filter_map(|axis| {
                        let branch = problem.branches.get(*axis)?;
                        let origin = structure.atom(branch.axis.0)?.position;
                        let endpoint = structure.atom(branch.axis.1)?.position;
                        let rotation_axis = normalize_vec(sub_vec(endpoint, origin));
                        let derivative = branch
                            .moving
                            .iter()
                            .filter_map(|atom_id| {
                                let atom = structure.atom(*atom_id)?;
                                let map_gradient = evidence.atom_gradients.get(atom_id)?;
                                let tangent =
                                    cross_vec(rotation_axis, sub_vec(atom.position, origin));
                                Some(
                                    map_gradient[0] * tangent.x
                                        + map_gradient[1] * tangent.y
                                        + map_gradient[2] * tangent.z,
                                )
                            })
                            .sum::<f64>();
                        derivative.is_finite().then_some((*axis, derivative))
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        evaluations = evaluations.saturating_add(1);
        let maximum_gradient = gradients
            .iter()
            .map(|(_, value)| value.abs())
            .max_by(f64::total_cmp)
            .unwrap_or(0.0);
        let mut trials = Vec::with_capacity(axes.len() * 2 + 1);
        for axis in axes {
            let dimension = problem.angle_dimensions + *axis;
            for direction in [-1.0, 1.0] {
                let mut trial = point.clone();
                trial[dimension] = wrap_degrees(trial[dimension] + direction * step);
                trials.push(trial);
            }
        }
        // A simultaneous gradient step is important for the common case in
        // which neither phi nor psi is favourable on its own but the ring
        // orientation improves when both linkages move together.
        if maximum_gradient > 1.0e-8 {
            let mut trial = point.clone();
            for (axis, derivative) in &gradients {
                let dimension = problem.angle_dimensions + *axis;
                trial[dimension] = wrap_degrees(trial[dimension] + step * derivative.signum());
            }
            trials.push(trial);
        }
        let mut best_trial = None::<(f64, Vec<f64>)>;
        for trial in trials {
            let Some((trial_structure, _)) = problem.structure(context, &trial) else {
                continue;
            };
            if max_vdw_overlap_pair(&trial_structure, vdw).0 > 1.20 {
                continue;
            }
            evaluations = evaluations.saturating_add(1);
            let value = progressive_branch_value(
                problem,
                context,
                &trial,
                placed,
                child,
                axes,
                vdw,
                child_target,
                placed_target,
                Some(region),
                anchor,
            );
            if best_trial
                .as_ref()
                .is_none_or(|(current, _)| value > *current)
            {
                best_trial = Some((value, trial));
            }
        }
        if let Some((value, trial)) = best_trial
            && value > best_value + 1.0e-5
        {
            best_value = value;
            point = trial;
            stagnant = 0;
        } else {
            stagnant += 1;
            if stagnant >= 3 {
                break;
            }
        }
    }
    (point, evaluations)
}

fn progressive_child_is_connected(
    problem: &DensitySwarmProblem<'_>,
    context: &DensityParticleContext,
    position: &[f64],
    child: &ResidueId,
    axes: &[usize],
) -> bool {
    problem
        .structure(context, position)
        .is_some_and(|(structure, _)| {
            let (path, ring) = frontier_child_support(problem, &structure, child, axes);
            path >= 0.02 && ring >= FRONTIER_MIN_RING_SUPPORT * 0.5
        })
}

fn correlated_arm_search(
    problem: &DensitySwarmProblem<'_>,
    sites: &[SearchSite],
    context: &DensityParticleContext,
    initial: &[f64],
    native_torsions: &BTreeMap<DensityParticleContext, Vec<f64>>,
    arms: &[ConnectedArm],
    vdw: &VdwClashContext,
    effort: DensityEffort,
) -> (Vec<f64>, usize, Vec<DensityArmEvidence>) {
    let Some(recipient_native) = native_torsions.get(context) else {
        return (initial.to_vec(), 0, Vec::new());
    };
    let mut point = initial.to_vec();
    let mut evaluations = 0usize;
    let mut evidence_records = Vec::new();
    for arm in arms {
        let arm_evaluation_start = evaluations;
        let modes = native_arm_modes(arm, sites, native_torsions);
        if modes.is_empty() {
            continue;
        }
        let before = pattern_objective_with_vdw(problem, context, &point, vdw);
        evaluations = evaluations.saturating_add(1);
        let mut screened = modes
            .par_iter()
            .map(|mode| {
                let mut trial = point.clone();
                for (mode_axis, branch_index) in arm.axes.iter().enumerate() {
                    let Some(recipient) = recipient_native.get(*branch_index) else {
                        continue;
                    };
                    trial[problem.angle_dimensions + branch_index] =
                        wrap_degrees(mode.torsions[mode_axis] - recipient);
                }
                let proposal_score = problem
                    .structure(context, &trial)
                    .map(|(structure, _)| {
                        if matches!(effort, DensityEffort::Deep) {
                            frontier_connected_arm_objective(
                                problem,
                                &structure,
                                &BTreeSet::new(),
                                arm,
                            )
                        } else {
                            problem.objective_value(context, &trial)
                        }
                    })
                    .unwrap_or(f64::NEG_INFINITY);
                (proposal_score, mode.clone(), trial)
            })
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(screened.len());
        screened.sort_by(|left, right| {
            right
                .0
                .total_cmp(&left.0)
                .then_with(|| left.1.id.cmp(&right.1.id))
        });
        let improvement_bound = screened
            .first()
            .map(|entry| (entry.0 - problem.objective_value(context, &point)).max(0.0))
            .unwrap_or(0.0);
        let exact_limit = if matches!(effort, DensityEffort::Deep) {
            // The arm score above is a complete connected-subtree screen.
            // Exact masked scoring only the leading modes avoids the old
            // 48-per-arm tail while retaining low-population alternatives.
            24
        } else {
            12
        };
        let mut exact = screened
            .into_par_iter()
            .take(exact_limit)
            .filter_map(|(_, mode, trial)| {
                let (structure, _) = problem.structure(context, &trial)?;
                if max_vdw_overlap_pair(&structure, vdw).0 > 0.75 {
                    return None;
                }
                Some((
                    pattern_objective_structure(&structure, 1.0, problem, vdw),
                    mode,
                    trial,
                ))
            })
            .collect::<Vec<_>>();
        evaluations = evaluations.saturating_add(exact.len());
        exact.sort_by(|left, right| {
            right
                .0
                .total_cmp(&left.0)
                .then_with(|| left.1.id.cmp(&right.1.id))
        });
        let best_entry = exact.first().cloned();
        let mut selected_mode = "native".to_string();
        let mut source_ids = context_conformer_ids(sites, context);
        let mut after = before;
        if let Some((objective, mode, trial)) = &best_entry
            && *objective > before + 1.0e-4
        {
            point = trial.clone();
            after = *objective;
            selected_mode = mode.id.clone();
            source_ids = context_conformer_ids(sites, &mode.context);
        }

        // Cross the common parent/child saddle with a small deterministic
        // paired trust region around the selected correlated mode.
        let root_axes = arm
            .axes
            .iter()
            .copied()
            .filter(|axis| problem.branches[*axis].child_residue == arm.root_residue)
            .collect::<Vec<_>>();
        let child_axes = arm
            .axes
            .iter()
            .copied()
            .filter(|axis| problem.branches[*axis].parent_residue == arm.root_residue)
            .collect::<Vec<_>>();
        let mut pair_accepted = false;
        if !root_axes.is_empty() && !child_axes.is_empty() {
            let mut pair_trials = Vec::new();
            for root_delta in [-20.0, -10.0, 10.0, 20.0] {
                for child_delta in [-20.0, -10.0, 10.0, 20.0] {
                    let mut trial = point.clone();
                    for axis in &root_axes {
                        trial[problem.angle_dimensions + axis] =
                            wrap_degrees(trial[problem.angle_dimensions + axis] + root_delta);
                    }
                    for axis in &child_axes {
                        trial[problem.angle_dimensions + axis] =
                            wrap_degrees(trial[problem.angle_dimensions + axis] + child_delta);
                    }
                    pair_trials.push(trial);
                }
            }
            let mut pair_screened = pair_trials
                .into_par_iter()
                .map(|trial| {
                    let score = problem
                        .structure(context, &trial)
                        .map(|(structure, _)| {
                            if matches!(effort, DensityEffort::Deep) {
                                frontier_connected_arm_objective(
                                    problem,
                                    &structure,
                                    &BTreeSet::new(),
                                    arm,
                                )
                            } else {
                                problem.objective_value(context, &trial)
                            }
                        })
                        .unwrap_or(f64::NEG_INFINITY);
                    (score, trial)
                })
                .collect::<Vec<_>>();
            evaluations = evaluations.saturating_add(pair_screened.len());
            pair_screened.sort_by(|left, right| right.0.total_cmp(&left.0));
            let pair_exact = pair_screened
                .into_par_iter()
                .take(4)
                .filter_map(|(_, trial)| {
                    let (structure, _) = problem.structure(context, &trial)?;
                    if max_vdw_overlap_pair(&structure, vdw).0 > 0.75 {
                        return None;
                    }
                    Some((
                        pattern_objective_structure(&structure, 1.0, problem, vdw),
                        trial,
                    ))
                })
                .collect::<Vec<_>>();
            evaluations = evaluations.saturating_add(pair_exact.len());
            for (objective, trial) in pair_exact {
                if objective > after + 1.0e-4 {
                    point = trial;
                    after = objective;
                    pair_accepted = true;
                }
            }
        }

        let mut alternatives = {
            let maximum = exact
                .iter()
                .map(|entry| entry.0)
                .max_by(f64::total_cmp)
                .unwrap_or(before);
            let normalization = exact
                .iter()
                .take(5)
                .map(|entry| (entry.0 - maximum).exp())
                .sum::<f64>()
                .max(1.0e-30);
            exact
                .iter()
                .take(5)
                .map(|(objective, mode, _)| DensityArmAlternative {
                    mode_id: mode.id.clone(),
                    source_conformer_ids: context_conformer_ids(sites, &mode.context),
                    population_prior: mode.population,
                    objective: *objective,
                    posterior_weight: (*objective - maximum).exp() / normalization,
                    cumulative_posterior_weight: 0.0,
                    in_credible_set: true,
                })
                .collect::<Vec<_>>()
        };
        let mut cumulative = 0.0;
        for alternative in &mut alternatives {
            let before = cumulative;
            cumulative = (cumulative + alternative.posterior_weight).min(1.0);
            alternative.cumulative_posterior_weight = cumulative;
            alternative.in_credible_set = before < 0.95;
        }
        let top_weight = alternatives
            .first()
            .map(|alternative| alternative.posterior_weight)
            .unwrap_or(0.0);
        let structure = problem.structure(context, &point).map(|entry| entry.0);
        let score = structure
            .as_ref()
            .and_then(|structure| problem.density_score(structure, problem.targets));
        let arm_set = arm.residues.iter().cloned().collect::<BTreeSet<_>>();
        // Arm evidence must be candidate independent: compare the complete
        // connected subtree with the exact same pose and fixed ROI after that
        // subtree is removed. This prevents a misplaced arm from claiming the
        // likelihood supplied by the core or by another branch.
        let without_arm_targets = problem
            .targets
            .iter()
            .filter_map(|target| {
                let mut target = target.clone();
                target
                    .glycan_residues
                    .retain(|residue| !arm_set.contains(residue));
                (!target.glycan_residues.is_empty()).then_some(target)
            })
            .collect::<Vec<_>>();
        let without_arm_score = structure.as_ref().and_then(|structure| {
            (!without_arm_targets.is_empty())
                .then(|| problem.density_score(structure, &without_arm_targets))
                .flatten()
        });
        if without_arm_score.is_some() {
            evaluations = evaluations.saturating_add(1);
        }
        let (ring_support, linkage_support, fixed_gain, voxel_count) = score
            .as_ref()
            .map(|score| {
                let residue_values = score
                    .residue_support
                    .iter()
                    .filter(|entry| arm_set.contains(&entry.residue))
                    .map(|entry| entry.ring_support)
                    .collect::<Vec<_>>();
                let linkage_values = score
                    .linkage_support
                    .iter()
                    .filter(|entry| {
                        arm_set.contains(&entry.donor) || arm_set.contains(&entry.acceptor)
                    })
                    .map(|entry| entry.support)
                    .collect::<Vec<_>>();
                (
                    if residue_values.is_empty() {
                        0.0
                    } else {
                        residue_values.iter().sum::<f64>() / residue_values.len() as f64
                    },
                    if linkage_values.is_empty() {
                        0.0
                    } else {
                        linkage_values.iter().sum::<f64>() / linkage_values.len() as f64
                    },
                    without_arm_score
                        .as_ref()
                        .map_or(score.likelihood_gain, |without| {
                            score.likelihood_gain - without.likelihood_gain
                        }),
                    score.voxel_count,
                )
            })
            .unwrap_or((0.0, 0.0, 0.0, 0));
        let bic_penalty = 0.5 * arm.axes.len() as f64 * (voxel_count.max(3) as f64).ln();
        let evidence_adjusted_gain = fixed_gain - bic_penalty;
        let classification = classify_arm_evidence(
            fixed_gain,
            bic_penalty,
            top_weight,
            linkage_support,
            after > before + 1.0e-4,
        );
        evidence_records.push(DensityArmEvidence {
            label: arm.label.clone(),
            parent_residue: arm.parent_residue.clone(),
            root_residue: arm.root_residue.clone(),
            residues: arm.residues.clone(),
            classification: classification.into(),
            selected_mode,
            source_conformer_ids: source_ids,
            fixed_roi_likelihood_gain: fixed_gain,
            normalized_density_gain: normalized_arm_density_gain(
                structure.as_ref(),
                &arm.residues,
                fixed_gain,
            ),
            prior_log_probability: alternatives
                .first()
                .map(|alternative| alternative.population_prior.max(1.0e-300).ln())
                .unwrap_or(0.0),
            clash_score: structure
                .as_ref()
                .map(|structure| -max_vdw_overlap_pair(structure, vdw).0.max(0.0))
                .unwrap_or(0.0),
            selected_mode_posterior: top_weight,
            credible_mass: 0.95,
            credible_set_size: alternatives
                .iter()
                .filter(|alternative| alternative.in_credible_set)
                .count(),
            bic_penalty,
            ring_support,
            linkage_path_support: linkage_support,
            proposal_level: if pair_accepted {
                "parent_child_pair"
            } else {
                "native_subtree_mode"
            }
            .into(),
            improvement_bound,
            evaluations: evaluations.saturating_sub(arm_evaluation_start),
            escalation_reason: if after > before + 1.0e-4 && evidence_adjusted_gain > 0.0 {
                "connected arm likelihood improved"
            } else if after > before + 1.0e-4 {
                "objective improved but arm-removal evidence did not exceed complexity penalty"
            } else {
                "native arm modes exhausted without evidence-adjusted gain"
            }
            .into(),
            pre_repair_objective: before,
            post_repair_objective: after,
            alternatives,
        });
    }
    (point, evaluations, evidence_records)
}

/// Build per-arm heterogeneous alternatives for the adaptive path.
///
/// The adaptive connected-arm beam computes per-arm mode diversity but only
/// returns the single best position, and the resulting arm evidence is
/// recomputed from an empty `previous` list, so `DensityArmEvidence`
/// `alternatives` stays empty (the runtime confirmed a single 99.7%-posterior
/// candidate even though every arm classified "ambiguous").  This helper
/// reconstructs the distinct GlycoShape arm modes for the fitted context,
/// ranks them with the same cheap density screen used by the beam, and
/// returns one `DensityArmEvidence` per arm whose `alternatives` carry the
/// modes and normalized posterior weights.  Passing these as `previous` into
/// `recompute_final_arm_evidence` preserves them in the final diagnostic.
/// It is pure reporting: none of these alternatives feeds ranking or the
/// chosen `fitted.pdb`, and the deposited reference is never consulted.
fn adaptive_arm_alternatives(
    problem: &DensitySwarmProblem<'_>,
    sites: &[SearchSite],
    context: &DensityParticleContext,
    initial: &[f64],
    native_torsions: &BTreeMap<DensityParticleContext, Vec<f64>>,
) -> Vec<DensityArmEvidence> {
    let arms = connected_arm_definitions(problem.branches);
    let Some(recipient_native) = native_torsions.get(context) else {
        return Vec::new();
    };
    if arms.is_empty() || problem.deadline_reached() {
        return Vec::new();
    }
    let mut records = Vec::with_capacity(arms.len());
    for arm in arms.iter().take(2) {
        let modes = native_arm_modes_all(arm, sites, native_torsions);
        // Score every distinct mode cheaply.  For level-3/512 this is a few
        // hundred fast-density screens per arm, which is small relative to the
        // full fit and is deliberately bounded to the two leading arms.
        // The native arm dictionary is a reporting diagnostic, not a
        // proposal dependency.  Evaluate its independent members in the
        // shared Rayon pool, then collect in the original indexed order so
        // marginalization and tie-breaking remain reproducible across thread
        // counts.  This avoids a serial map/protein-background traversal for
        // every level-3 conformer while retaining exactly the same modes.
        let entries = modes
            .par_iter()
            .filter_map(|mode| {
                let mut trial = initial.to_vec();
                for (local, axis) in arm.axes.iter().enumerate() {
                    let native = recipient_native.get(*axis)?;
                    trial[problem.angle_dimensions + *axis] =
                        wrap_degrees(mode.torsions[local] - native);
                }
                let objective = adaptive_arm_screen_position(problem, context, &trial)?;
                Some((objective, mode.clone()))
            })
            .collect::<Vec<_>>();
        if problem.deadline_reached() {
            break;
        }
        let alternatives = marginal_arm_mode_alternatives(arm, sites, entries, 0.95, 10);
        if alternatives.is_empty() {
            continue;
        }
        let selected = alternatives
            .first()
            .map(|alternative| alternative.mode_id.clone())
            .unwrap_or_else(|| "native".into());
        let source_ids = alternatives
            .first()
            .map(|alternative| alternative.source_conformer_ids.clone())
            .unwrap_or_default();
        records.push(DensityArmEvidence {
            label: arm.label.clone(),
            parent_residue: arm.parent_residue.clone(),
            root_residue: arm.root_residue.clone(),
            residues: arm.residues.clone(),
            classification: "ambiguous".into(),
            selected_mode: selected,
            source_conformer_ids: source_ids,
            fixed_roi_likelihood_gain: 0.0,
            normalized_density_gain: 0.0,
            prior_log_probability: alternatives
                .first()
                .map(|alternative| alternative.population_prior.max(1.0e-300).ln())
                .unwrap_or(0.0),
            clash_score: 0.0,
            selected_mode_posterior: alternatives
                .first()
                .map(|alternative| alternative.posterior_weight)
                .unwrap_or(0.0),
            credible_mass: 0.95,
            credible_set_size: alternatives
                .iter()
                .filter(|alternative| alternative.in_credible_set)
                .count(),
            bic_penalty: 0.0,
            ring_support: 0.0,
            linkage_path_support: 0.0,
            proposal_level: "adaptive_alternatives".into(),
            improvement_bound: 0.0,
            evaluations: 0,
            escalation_reason: "diagnostic alternatives from adaptive arm screen".into(),
            pre_repair_objective: 0.0,
            post_repair_objective: 0.0,
            alternatives,
        });
    }
    records
}

#[derive(Debug)]
struct MarginalArmMode {
    key: Vec<i16>,
    log_weight: f64,
    population: f64,
    source_conformer_ids: Vec<String>,
}

fn arm_torsion_mode_key(torsions: &[f64]) -> Vec<i16> {
    // Distinct arm modes are defined by the arm-root linkage basin.  Distal
    // conformers within the same root basin are nuisance microstates and are
    // marginalized into it.  Four phi quadrants and two psi hemispheres give
    // at most eight interpretable modes, so a capped ten-model output can
    // still carry the complete 95% credible mass.
    torsions
        .iter()
        .take(2)
        .enumerate()
        .map(|(index, angle)| {
            let width = if index == 0 { 90.0 } else { 180.0 };
            let bins = if index == 0 { 4 } else { 2 };
            (angle.rem_euclid(360.0) / width).round() as i16 % bins
        })
        .collect()
}

fn log_add_exp(left: f64, right: f64) -> f64 {
    if !left.is_finite() {
        return right;
    }
    if !right.is_finite() {
        return left;
    }
    let maximum = left.max(right);
    maximum + ((left - maximum).exp() + (right - maximum).exp()).ln()
}

/// Marginalize individual GlycoShape members into distinct arm torsion modes.
///
/// Every entry was scored with the same fitted core and the same sibling-arm
/// coordinates.  Summing member probabilities inside a mode therefore gives
/// an arm-local posterior; it cannot be collapsed by the posterior of a
/// strongly supported sibling arm.
fn marginal_arm_mode_alternatives(
    arm: &ConnectedArm,
    sites: &[SearchSite],
    entries: Vec<(f64, NativeArmMode)>,
    credible_mass: f64,
    maximum_modes: usize,
) -> Vec<DensityArmAlternative> {
    let mut modes = BTreeMap::<Vec<i16>, MarginalArmMode>::new();
    for (objective, mode) in entries {
        if !objective.is_finite() {
            continue;
        }
        let key = arm_torsion_mode_key(&mode.torsions);
        let population = mode.population.max(1.0e-300);
        let member_log_weight = objective + population.ln();
        let source_ids = context_conformer_ids(sites, &mode.context);
        modes
            .entry(key.clone())
            .and_modify(|aggregate| {
                aggregate.log_weight = log_add_exp(aggregate.log_weight, member_log_weight);
                aggregate.population += population;
                aggregate.source_conformer_ids.extend(source_ids.clone());
            })
            .or_insert(MarginalArmMode {
                key,
                log_weight: member_log_weight,
                population,
                source_conformer_ids: source_ids,
            });
    }
    let mut modes = modes.into_values().collect::<Vec<_>>();
    modes.sort_by(|left, right| {
        right
            .log_weight
            .total_cmp(&left.log_weight)
            .then_with(|| left.key.cmp(&right.key))
    });
    let maximum = modes
        .iter()
        .map(|mode| mode.log_weight)
        .max_by(f64::total_cmp)
        .unwrap_or(0.0);
    let normalization = modes
        .iter()
        .map(|mode| (mode.log_weight - maximum).exp())
        .sum::<f64>()
        .max(1.0e-300);
    let mut cumulative = 0.0;
    let mut alternatives = Vec::new();
    for (index, mut mode) in modes.into_iter().enumerate() {
        if alternatives.len() >= maximum_modes.max(1) {
            break;
        }
        mode.source_conformer_ids.sort();
        mode.source_conformer_ids.dedup();
        let posterior = (mode.log_weight - maximum).exp() / normalization;
        cumulative = (cumulative + posterior).min(1.0);
        alternatives.push(DensityArmAlternative {
            mode_id: format!("{}-marginal-mode-{}", arm.label, index + 1),
            source_conformer_ids: mode.source_conformer_ids,
            population_prior: mode.population,
            objective: mode.log_weight,
            posterior_weight: posterior,
            cumulative_posterior_weight: cumulative,
            in_credible_set: cumulative - posterior < credible_mass,
        });
        if cumulative >= credible_mass {
            break;
        }
    }
    alternatives
}

fn recompute_final_arm_evidence(
    problem: &DensitySwarmProblem<'_>,
    structure: &Structure,
    arms: &[ConnectedArm],
    previous: Vec<DensityArmEvidence>,
    vdw: &VdwClashContext,
) -> Vec<DensityArmEvidence> {
    let Some(full) = problem.density_score(structure, problem.targets) else {
        return previous;
    };
    let final_objective = pattern_objective_structure(structure, 1.0, problem, vdw);
    let previous = previous
        .into_iter()
        .map(|record| (record.label.clone(), record))
        .collect::<BTreeMap<_, _>>();
    arms.iter()
        .map(|arm| {
            let arm_set = arm.residues.iter().cloned().collect::<BTreeSet<_>>();
            let without_targets = problem
                .targets
                .iter()
                .filter_map(|target| {
                    let mut target = target.clone();
                    target
                        .glycan_residues
                        .retain(|residue| !arm_set.contains(residue));
                    (!target.glycan_residues.is_empty()).then_some(target)
                })
                .collect::<Vec<_>>();
            let without = (!without_targets.is_empty())
                .then(|| problem.density_score(structure, &without_targets))
                .flatten();
            let gain = without.as_ref().map_or(full.likelihood_gain, |score| {
                full.likelihood_gain - score.likelihood_gain
            });
            let bic = 0.5 * arm.axes.len() as f64 * (full.voxel_count.max(3) as f64).ln();
            let residue_values = full
                .residue_support
                .iter()
                .filter(|entry| arm_set.contains(&entry.residue))
                .map(|entry| entry.ring_support)
                .collect::<Vec<_>>();
            let linkage_values = full
                .linkage_support
                .iter()
                .filter(|entry| arm_set.contains(&entry.donor) || arm_set.contains(&entry.acceptor))
                .map(|entry| entry.support)
                .collect::<Vec<_>>();
            let ring_support = if residue_values.is_empty() {
                0.0
            } else {
                residue_values.iter().sum::<f64>() / residue_values.len() as f64
            };
            let linkage_path_support = if linkage_values.is_empty() {
                0.0
            } else {
                linkage_values.iter().sum::<f64>() / linkage_values.len() as f64
            };
            let old = previous.get(&arm.label);
            let top_weight = old
                .and_then(|record| record.alternatives.first())
                .map(|alternative| alternative.posterior_weight)
                .unwrap_or(0.0);
            DensityArmEvidence {
                label: arm.label.clone(),
                parent_residue: arm.parent_residue.clone(),
                root_residue: arm.root_residue.clone(),
                residues: arm.residues.clone(),
                classification: classify_arm_evidence(
                    gain,
                    bic,
                    top_weight,
                    linkage_path_support,
                    true,
                )
                .into(),
                selected_mode: old
                    .map_or_else(|| "native".into(), |record| record.selected_mode.clone()),
                source_conformer_ids: old
                    .map(|record| record.source_conformer_ids.clone())
                    .unwrap_or_default(),
                fixed_roi_likelihood_gain: gain,
                normalized_density_gain: normalized_arm_density_gain(
                    Some(structure),
                    &arm.residues,
                    gain,
                ),
                prior_log_probability: old.map_or(0.0, |record| {
                    record
                        .alternatives
                        .first()
                        .map(|alternative| alternative.population_prior.max(1.0e-300).ln())
                        .unwrap_or(record.prior_log_probability)
                }),
                clash_score: -max_vdw_overlap_pair(structure, vdw).0.max(0.0),
                selected_mode_posterior: top_weight,
                credible_mass: old.map_or(0.95, |record| record.credible_mass),
                credible_set_size: old.map_or(0, |record| {
                    record
                        .alternatives
                        .iter()
                        .filter(|alternative| alternative.in_credible_set)
                        .count()
                }),
                bic_penalty: bic,
                ring_support,
                linkage_path_support,
                proposal_level: old.map_or_else(
                    || "final_recomputed".into(),
                    |record| format!("{}_final_recomputed", record.proposal_level),
                ),
                improvement_bound: old.map_or(0.0, |record| record.improvement_bound),
                evaluations: old.map_or(1, |record| record.evaluations.saturating_add(1)),
                escalation_reason: "evidence recomputed from final exported coordinates".into(),
                pre_repair_objective: old
                    .map_or(final_objective, |record| record.post_repair_objective),
                post_repair_objective: final_objective,
                alternatives: old
                    .map(|record| record.alternatives.clone())
                    .unwrap_or_default(),
            }
        })
        .collect()
}

fn normalized_arm_density_gain(
    structure: Option<&Structure>,
    residues: &[ResidueId],
    gain: f64,
) -> f64 {
    let residue_set = residues.iter().collect::<BTreeSet<_>>();
    let heavy_atoms = structure
        .map(|structure| {
            structure
                .atoms()
                .into_iter()
                .filter(|atom| {
                    residue_set.contains(&atom.residue) && !atom.element.eq_ignore_ascii_case("H")
                })
                .count()
        })
        .unwrap_or(0);
    gain / heavy_atoms.max(1) as f64
}

const UNSUPPORTED_ARM_GAIN_EPSILON: f64 = -1.0e-6;

/// Replace experimentally unsupported arms with an ensemble-prior mode.
///
/// Selection is deliberately independent of density: modes are tried in
/// descending population order and the first chemically compatible complete
/// subtree is accepted.  Density is evaluated only afterwards so the report
/// can state how the prior-supplied coordinates interact with the map.
fn apply_unsupported_arm_priors(
    problem: &DensitySwarmProblem<'_>,
    sites: &[SearchSite],
    pose: &mut GlobalDensityPose,
    arms: &[ConnectedArm],
    native_torsions: &BTreeMap<DensityParticleContext, Vec<f64>>,
    vdw: &VdwClashContext,
) -> usize {
    if arms.is_empty() || native_torsions.is_empty() {
        return 0;
    }
    let context = pose
        .outcome
        .sites
        .iter()
        .map(|site| site.conformer_index)
        .collect::<Vec<_>>();
    let position = position_from_pose(pose, problem.angle_dimensions);
    let alternatives =
        adaptive_arm_alternatives(problem, sites, &context, &position, native_torsions);
    let evidence = recompute_final_arm_evidence(problem, &pose.structure, arms, alternatives, vdw);
    let unsupported = evidence
        .iter()
        .filter(|record| record.fixed_roi_likelihood_gain < UNSUPPORTED_ARM_GAIN_EPSILON)
        .map(|record| (record.label.clone(), record.fixed_roi_likelihood_gain))
        .collect::<BTreeMap<_, _>>();
    if unsupported.is_empty() {
        pose.arm_evidence = evidence;
        return 0;
    }

    let mut selections =
        BTreeMap::<String, (String, Vec<String>, Vec<DensityArmAlternative>, f64)>::new();
    let mut structure = pose.structure.clone();
    let mut evaluations = 0usize;
    for arm in arms {
        let Some(original_gain) = unsupported.get(&arm.label).copied() else {
            continue;
        };
        let Some(root_branch) = problem.branches.iter().find(|branch| {
            branch.parent_residue == arm.parent_residue && branch.child_residue == arm.root_residue
        }) else {
            continue;
        };
        let modes = native_arm_modes_all(arm, sites, native_torsions);
        let prior_alternatives = marginal_arm_mode_alternatives(
            arm,
            sites,
            modes.iter().cloned().map(|mode| (0.0, mode)).collect(),
            0.95,
            10,
        );
        let target_positions = structure
            .atoms()
            .into_iter()
            .map(|atom| (atom.id, atom.position))
            .collect::<BTreeMap<_, _>>();
        let active = arm.residues.iter().cloned().collect::<BTreeSet<_>>();
        let mut selected = None;
        for mode in modes {
            let Some(source_positions) = problem.template_positions.get(&mode.context) else {
                continue;
            };
            let Some(positions) = transplant_arm_positions(
                problem.base_template,
                source_positions,
                &target_positions,
                arm,
                root_branch,
            ) else {
                continue;
            };
            let mut candidate = structure.clone();
            if candidate
                .set_atom_positions(positions.iter().map(|(atom, position)| (*atom, *position)))
                .is_err()
            {
                continue;
            }
            evaluations = evaluations.saturating_add(1);
            if max_vdw_overlap_pair_active(&candidate, vdw, &active).0 > 1.20 {
                continue;
            }
            let source_ids = context_conformer_ids(sites, &mode.context);
            let selected_mode = prior_alternatives
                .iter()
                .find(|alternative| {
                    source_ids
                        .iter()
                        .any(|id| alternative.source_conformer_ids.contains(id))
                })
                .map(|alternative| alternative.mode_id.clone())
                .unwrap_or(mode.id);
            selected = Some((candidate, selected_mode, source_ids));
            break;
        }
        if let Some((candidate, selected_mode, source_ids)) = selected {
            structure = candidate;
            selections.insert(
                arm.label.clone(),
                (selected_mode, source_ids, prior_alternatives, original_gain),
            );
        }
    }
    if selections.is_empty() {
        pose.arm_evidence = evidence;
        return evaluations;
    }
    let applied = if let Some(score) = problem.density_score(&structure, problem.targets) {
        evaluations = evaluations.saturating_add(1);
        pose.structure = structure;
        pose.score = score;
        pose.support_score = density_support_score(&pose.score);
        pose.steric_score = steric_score(&pose.structure, problem.clash_distance);
        pose.stage = "adaptive evidence-aware arm assembly";
        true
    } else {
        false
    };
    if !applied {
        pose.arm_evidence = evidence;
        return evaluations;
    }
    let mut final_evidence =
        recompute_final_arm_evidence(problem, &pose.structure, arms, evidence, vdw);
    for record in &mut final_evidence {
        let Some((mode, sources, alternatives, original_gain)) = selections.get(&record.label)
        else {
            continue;
        };
        record.classification = "ensemble_prior_determined".into();
        record.selected_mode = mode.clone();
        record.source_conformer_ids = sources.clone();
        record.alternatives = alternatives.clone();
        record.selected_mode_posterior = alternatives
            .iter()
            .find(|alternative| alternative.mode_id == *mode)
            .map(|alternative| alternative.posterior_weight)
            .unwrap_or(0.0);
        record.credible_set_size = alternatives
            .iter()
            .filter(|alternative| alternative.in_credible_set)
            .count();
        record.prior_log_probability = alternatives
            .iter()
            .find(|alternative| alternative.mode_id == *mode)
            .map(|alternative| alternative.population_prior.max(1.0e-300).ln())
            .unwrap_or(0.0);
        record.proposal_level = "ensemble_prior_fallback".into();
        record.escalation_reason = format!(
            "density-driven arm rejected after negative fixed-ROI gain ({original_gain:.4}); coordinates selected from the ensemble population prior"
        );
    }
    pose.arm_evidence = final_evidence;
    evaluations
}

/// Debug-only per-linkage torsion distribution across the supplied ensemble,
/// binned into 30-degree windows so the deposited geometry can be compared
/// against the ensemble modes.
#[cfg(test)]
fn debug_torsion_distribution(
    templates: &BTreeMap<DensityParticleContext, Structure>,
    branches: &[BranchRotation],
) {
    let mut bins = std::collections::BTreeMap::<usize, [usize; 12]>::new();
    let mut totals = std::collections::BTreeMap::<usize, usize>::new();
    for structure in templates.values() {
        for (index, branch) in branches.iter().enumerate() {
            if let Some(value) = branch_torsion_degrees(structure, branch) {
                let bin = (value.rem_euclid(360.0) / 30.0).floor() as usize % 12;
                bins.entry(index).or_insert([0; 12])[bin] += 1;
                *totals.entry(index).or_insert(0) += 1;
            }
        }
    }
    for (index, branch) in branches.iter().enumerate() {
        let total = totals.get(&index).copied().unwrap_or(0);
        let counts = bins.get(&index).copied().unwrap_or([0; 12]);
        let modes = counts
            .iter()
            .enumerate()
            .filter_map(|(bin, count)| {
                if *count > 0 {
                    Some((bin * 30, *count))
                } else {
                    None
                }
            })
            .collect::<Vec<_>>();
        eprintln!(
            "torsion-debug: {:<42} n={:>3} bins={:?}",
            branch.label,
            total,
            modes
                .iter()
                .map(|(bin, count)| format!("{}:{}", bin, count))
                .collect::<Vec<_>>()
                .join(" ")
        );
    }
}

/// Explicit glycosidic degrees of freedom used by the swarm path.  Every
/// linkage contributes a φ axis on the anomeric bond and a ψ axis on the
/// acceptor C--O bond.  A parent 1→6 linkage additionally contributes ω on
/// C5--C6.  All axes move only the child subtree, so protein atoms, parent
/// rings, and sugar-ring internal coordinates remain fixed.
fn explicit_branch_rotations(
    structure: &Structure,
    targets: &[DensityTarget],
) -> Vec<BranchRotation> {
    let target_ids = targets
        .iter()
        .flat_map(|target| target.glycan_residues.iter().cloned())
        .collect::<BTreeSet<_>>();
    let root_atoms = structure
        .metadata()
        .glycosylation_sites
        .iter()
        .filter(|site| {
            targets
                .iter()
                .any(|target| target.site == site.protein_residue)
        })
        .filter_map(|site| structure.find_atom(&site.glycan_residue, &site.glycan_atom))
        .collect::<BTreeSet<_>>();
    let atom_by_id = structure
        .atoms()
        .into_iter()
        .map(|atom| (atom.id, atom))
        .collect::<BTreeMap<_, _>>();
    let mut seen = BTreeSet::<(AtomId, AtomId, String)>::new();
    let mut branches = Vec::new();
    for (left, right) in structure.bonds() {
        let (Some(left_atom), Some(right_atom)) = (atom_by_id.get(&left), atom_by_id.get(&right))
        else {
            continue;
        };
        if left_atom.residue == right_atom.residue
            || !target_ids.contains(&left_atom.residue)
            || !target_ids.contains(&right_atom.residue)
        {
            continue;
        }
        let left_component = atom_component(structure, left, right, &target_ids);
        let right_component = atom_component(structure, right, left, &target_ids);
        let (moving, child_atom, parent_atom, child_residue, parent_residue) = if !left_component
            .is_empty()
            && left_component.iter().all(|atom| !root_atoms.contains(atom))
        {
            (
                left_component,
                left,
                right,
                left_atom.residue.clone(),
                right_atom.residue.clone(),
            )
        } else if !right_component.is_empty()
            && right_component
                .iter()
                .all(|atom| !root_atoms.contains(atom))
        {
            (
                right_component,
                right,
                left,
                right_atom.residue.clone(),
                left_atom.residue.clone(),
            )
        } else {
            continue;
        };
        if moving.len() == target_ids.len() {
            continue;
        }
        let moving = moving.into_iter().collect::<Vec<_>>();
        let child_c1 = structure
            .atoms()
            .into_iter()
            .find(|atom| {
                atom.residue == child_residue
                    && atom.name.trim().eq_ignore_ascii_case("C1")
                    && moving.contains(&atom.id)
            })
            .map(|atom| atom.id)
            .unwrap_or(child_atom);
        let linkage_axis = (child_c1, parent_atom);
        if seen.insert((linkage_axis.0, linkage_axis.1, "phi".into())) {
            branches.push(BranchRotation {
                axis: linkage_axis,
                moving: moving.clone(),
                residues: vec![child_residue.clone()],
                child_residue: child_residue.clone(),
                parent_residue: parent_residue.clone(),
                label: format!(
                    "{}:C1-{}:{} [phi]",
                    child_residue, parent_residue, atom_by_id[&parent_atom].name
                ),
            });
        }
        // The parent atom attached to the child anomeric carbon is normally
        // O3/O4/O6. Find its parent carbon through the explicit bond graph.
        let parent_acceptor = structure
            .bonds()
            .into_iter()
            .filter_map(|(first, second)| {
                if first == parent_atom {
                    Some(second)
                } else if second == parent_atom {
                    Some(first)
                } else {
                    None
                }
            })
            .find(|atom| {
                atom_by_id.get(atom).is_some_and(|value| {
                    value.residue == parent_residue && value.name.starts_with('C')
                })
            });
        if let Some(parent_acceptor) = parent_acceptor {
            if seen.insert((parent_acceptor, parent_atom, "psi".into())) {
                branches.push(BranchRotation {
                    axis: (parent_acceptor, parent_atom),
                    moving: moving.clone(),
                    residues: vec![child_residue.clone()],
                    child_residue: child_residue.clone(),
                    parent_residue: parent_residue.clone(),
                    label: format!(
                        "{}:{}-{}:{} [psi]",
                        parent_residue,
                        atom_by_id[&parent_acceptor].name,
                        parent_residue,
                        atom_by_id[&parent_atom].name
                    ),
                });
            }
            // O6 is the canonical exocyclic 1→6 acceptor.  Rotate C6 and
            // everything beyond it around C5--C6, preserving the parent ring.
            if atom_by_id[&parent_atom]
                .name
                .trim()
                .eq_ignore_ascii_case("O6")
            {
                let parent_c6 = structure
                    .bonds()
                    .into_iter()
                    .filter_map(|(first, second)| {
                        if first == parent_atom {
                            Some(second)
                        } else if second == parent_atom {
                            Some(first)
                        } else {
                            None
                        }
                    })
                    .find(|atom| {
                        atom_by_id.get(atom).is_some_and(|value| {
                            value.residue == parent_residue
                                && value.name.trim().eq_ignore_ascii_case("C6")
                        })
                    });
                if let Some(parent_c6) = parent_c6 {
                    let parent_c5 = structure
                        .bonds()
                        .into_iter()
                        .filter_map(|(first, second)| {
                            if first == parent_c6 {
                                Some(second)
                            } else if second == parent_c6 {
                                Some(first)
                            } else {
                                None
                            }
                        })
                        .find(|atom| {
                            atom_by_id.get(atom).is_some_and(|value| {
                                value.residue == parent_residue
                                    && value.name.trim().eq_ignore_ascii_case("C5")
                            })
                        });
                    if let Some(parent_c5) = parent_c5 {
                        let mut allowed = target_ids.clone();
                        allowed.insert(parent_residue.clone());
                        let omega_moving =
                            atom_component_allowed(structure, parent_c6, parent_c5, &allowed)
                                .into_iter()
                                .filter(|atom| *atom != parent_c5)
                                .collect::<Vec<_>>();
                        if !omega_moving.is_empty()
                            && seen.insert((parent_c5, parent_c6, "omega".into()))
                        {
                            branches.push(BranchRotation {
                                axis: (parent_c5, parent_c6),
                                moving: omega_moving,
                                residues: vec![child_residue.clone()],
                                child_residue: child_residue.clone(),
                                parent_residue: parent_residue.clone(),
                                label: format!(
                                    "{}:C5-{}:C6 [omega]",
                                    parent_residue, parent_residue
                                ),
                            });
                        }
                    }
                }
            }
        }
    }
    branches
}

fn atom_component_allowed(
    structure: &Structure,
    start: AtomId,
    blocked: AtomId,
    allowed_residues: &BTreeSet<ResidueId>,
) -> BTreeSet<AtomId> {
    let atom_residues = structure
        .atoms()
        .into_iter()
        .map(|atom| (atom.id, atom.residue.clone()))
        .collect::<BTreeMap<_, _>>();
    let mut component = BTreeSet::new();
    let mut pending = vec![start];
    while let Some(current) = pending.pop() {
        if !component.insert(current) {
            continue;
        }
        for (left, right) in structure.bonds() {
            if (left == current && right == blocked) || (right == current && left == blocked) {
                continue;
            }
            let next = if left == current {
                right
            } else if right == current {
                left
            } else {
                continue;
            };
            if next != blocked
                && atom_residues
                    .get(&next)
                    .is_some_and(|residue| allowed_residues.contains(residue))
            {
                pending.push(next);
            }
        }
    }
    component
}

fn atom_component(
    structure: &Structure,
    start: AtomId,
    blocked: AtomId,
    allowed_residues: &BTreeSet<ResidueId>,
) -> BTreeSet<AtomId> {
    let atoms = structure.atoms();
    let atom_residues = atoms
        .iter()
        .map(|atom| (atom.id, atom.residue.clone()))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut component = BTreeSet::new();
    let mut pending = vec![start];
    while let Some(current) = pending.pop() {
        if !component.insert(current) {
            continue;
        }
        for (left, right) in structure.bonds() {
            if (left == current && right == blocked) || (right == current && left == blocked) {
                continue;
            }
            let next = if left == current {
                right
            } else if right == current {
                left
            } else {
                continue;
            };
            if next != blocked
                && atom_residues
                    .get(&next)
                    .is_some_and(|residue| allowed_residues.contains(residue))
            {
                pending.push(next);
            }
        }
    }
    component
}

fn rotate_branch(
    structure: &mut Structure,
    branch: &BranchRotation,
    mut radians: f64,
) -> Result<()> {
    if branch.label.contains("[phi]") {
        radians = -radians;
    }
    let origin = structure
        .atom(branch.axis.0)
        .ok_or_else(|| RefineError::DensityNoPose)?
        .position;
    let endpoint = structure
        .atom(branch.axis.1)
        .ok_or_else(|| RefineError::DensityNoPose)?
        .position;
    let axis_vector = Vec3 {
        x: endpoint.x - origin.x,
        y: endpoint.y - origin.y,
        z: endpoint.z - origin.z,
    };
    let norm = (axis_vector.x.powi(2) + axis_vector.y.powi(2) + axis_vector.z.powi(2)).sqrt();
    if norm <= 1.0e-12 {
        return Err(RefineError::DensityNoPose);
    }
    let axis = Vec3 {
        x: axis_vector.x / norm,
        y: axis_vector.y / norm,
        z: axis_vector.z / norm,
    };
    let sine = radians.sin();
    let cosine = radians.cos();
    let updates = branch
        .moving
        .iter()
        .filter_map(|atom| structure.atom(*atom).map(|value| (*atom, value.position)))
        .map(|(atom, point)| {
            let relative = Vec3 {
                x: point.x - origin.x,
                y: point.y - origin.y,
                z: point.z - origin.z,
            };
            let cross = Vec3 {
                x: axis.y * relative.z - axis.z * relative.y,
                y: axis.z * relative.x - axis.x * relative.z,
                z: axis.x * relative.y - axis.y * relative.x,
            };
            let dot = axis.x * relative.x + axis.y * relative.y + axis.z * relative.z;
            let rotated = Vec3 {
                x: relative.x * cosine + cross.x * sine + axis.x * dot * (1.0 - cosine),
                y: relative.y * cosine + cross.y * sine + axis.y * dot * (1.0 - cosine),
                z: relative.z * cosine + cross.z * sine + axis.z * dot * (1.0 - cosine),
            };
            (
                atom,
                Vec3 {
                    x: origin.x + rotated.x,
                    y: origin.y + rotated.y,
                    z: origin.z + rotated.z,
                },
            )
        })
        .collect::<Vec<_>>();
    structure.set_atom_positions(updates)?;
    Ok(())
}

#[allow(dead_code)]
fn score_candidate(
    structure: &Structure,
    config: &DensityRefinementConfig,
) -> Result<DensityScore> {
    let targets = resolve_targets(structure, &config.targets)?;
    Ok(config.scorer.score(structure, &targets)?)
}

fn resolve_targets(structure: &Structure, targets: &[DensityTarget]) -> Result<Vec<DensityTarget>> {
    if targets.is_empty() {
        let all = DensityTarget::all(structure);
        if all.is_empty() {
            return Err(reglyco_density::DensityError::EmptyTarget.into());
        }
        return Ok(all);
    }
    targets
        .iter()
        .map(|target| {
            if target.glycan_residues.is_empty() {
                Ok(DensityTarget::for_site(structure, &target.site)?)
            } else {
                Ok(target.clone())
            }
        })
        .collect()
}

fn density_relaxation_options(
    structure: &Structure,
    base: &RelaxOptions,
    targets: &[DensityTarget],
) -> Result<RelaxOptions> {
    let resolved = resolve_targets(structure, targets)?;
    let mut residues = resolved
        .into_iter()
        .flat_map(|target| target.glycan_residues)
        .collect::<Vec<_>>();
    residues.sort();
    residues.dedup();
    if residues.is_empty() {
        return Err(reglyco_density::DensityError::EmptyTarget.into());
    }
    let mut options = base.clone();
    options.movable = MovableSelection::Residues(residues);
    options.include_local_sidechains = true;
    // Density fitting only relaxes a local glycan/side-chain neighborhood.
    // Distant protein atoms contribute a constant to that objective, so a
    // finite cutoff avoids repeatedly enumerating the complete 4,600-atom
    // protein pair set while retaining all local interactions.
    options.nonbonded_cutoff.get_or_insert(10.0);
    options.active_terms_only = true;
    Ok(options)
}

#[allow(dead_code)]
fn record_candidate(
    candidates: &mut Vec<DensityCandidate>,
    limit: usize,
    structure: &Structure,
    angles: &[(f64, f64)],
    offsets: &[f64],
    score: DensityScore,
    steric_score: f64,
) {
    if limit == 0 {
        return;
    }
    if let Some(existing) = candidates.iter_mut().find(|candidate| {
        (angle_distance(&candidate.angles_degrees, angles) < 1.0e-6
            && offset_distance(&candidate.glycosidic_torsion_offsets_degrees, offsets) < 1.0e-6)
            || structure_rmsd(&candidate.structure, structure) < 1.0e-3
    }) {
        if score.correlation > existing.correlation {
            existing.correlation = score.correlation;
            existing.steric_score = steric_score;
            existing.site_correlations = score.sites.iter().map(|site| site.correlation).collect();
            existing.glycosidic_torsion_offsets_degrees = offsets.to_vec();
            existing.structure = structure.clone();
        }
        return;
    }
    candidates.push(DensityCandidate {
        rank: 0,
        correlation: score.correlation,
        steric_score,
        angles_degrees: angles.to_vec(),
        glycosidic_torsion_offsets_degrees: offsets.to_vec(),
        site_correlations: score.sites.iter().map(|site| site.correlation).collect(),
        conformer_ids: Vec::new(),
        stage: "local".into(),
        support_score: score.supported_atom_fraction,
        posterior_weight: 0.0,
        cumulative_posterior: 0.0,
        likelihood_gain: score.likelihood_gain,
        heldout_likelihood_gain: score.heldout_likelihood_gain,
        difference_score: score.difference_score,
        prior_log_probability: 0.0,
        active_residues: score
            .residue_support
            .iter()
            .filter(|support| support.supported)
            .map(|support| support.residue.clone())
            .collect(),
        unsupported_residues: score
            .residue_support
            .iter()
            .filter(|support| !support.supported)
            .map(|support| support.residue.clone())
            .collect(),
        linkage_support: score.linkage_support.clone(),
        structure: structure.clone(),
    });
    candidates.sort_by(|left, right| right.correlation.total_cmp(&left.correlation));
    candidates.truncate(limit);
}

/// Compare candidate poses by coordinates rather than only by torsion labels.
/// This keeps `candidates.pdb` geometrically diverse when two parameter paths
/// happen to produce the same rigid pose.
fn structure_rmsd(left: &Structure, right: &Structure) -> f64 {
    let right_atoms = right
        .atoms()
        .into_iter()
        .map(|atom| (atom.id, atom))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut sum = 0.0;
    let mut count = 0usize;
    for atom in left.atoms() {
        if atom.element.eq_ignore_ascii_case("H") {
            continue;
        }
        let Some(other) = right_atoms.get(&atom.id) else {
            continue;
        };
        sum += (atom.position.x - other.position.x).powi(2)
            + (atom.position.y - other.position.y).powi(2)
            + (atom.position.z - other.position.z).powi(2);
        count += 1;
    }
    if count == 0 {
        f64::INFINITY
    } else {
        (sum / count as f64).sqrt()
    }
}

#[allow(dead_code)]
fn better_density(
    correlation: f64,
    angles: &[(f64, f64)],
    offsets: &[f64],
    best_correlation: f64,
    best_angles: &[(f64, f64)],
    best_offsets: &[f64],
) -> bool {
    correlation > best_correlation + 1.0e-10
        || ((correlation - best_correlation).abs() <= 1.0e-10
            && (compare_angles(angles, best_angles).is_lt()
                || (compare_angles(angles, best_angles).is_eq()
                    && compare_offsets(offsets, best_offsets).is_lt())))
}

fn better_density_score(
    score: &DensityScore,
    angles: &[(f64, f64)],
    offsets: &[f64],
    best_score: &DensityScore,
    best_angles: &[(f64, f64)],
    best_offsets: &[f64],
) -> bool {
    score.correlation > best_score.correlation + 1.0e-10
        || ((score.correlation - best_score.correlation).abs() <= 1.0e-10
            && (density_support_score(score) > density_support_score(best_score) + 1.0e-10
                || ((density_support_score(score) - density_support_score(best_score)).abs()
                    <= 1.0e-10
                    && (compare_angles(angles, best_angles).is_lt()
                        || (compare_angles(angles, best_angles).is_eq()
                            && compare_offsets(offsets, best_offsets).is_lt())))))
}

#[allow(dead_code)]
fn angle_distance(left: &[(f64, f64)], right: &[(f64, f64)]) -> f64 {
    left.iter()
        .zip(right)
        .map(|(&(left_phi, left_psi), &(right_phi, right_psi))| {
            periodic_difference(left_phi, right_phi).abs()
                + periodic_difference(left_psi, right_psi).abs()
        })
        .sum()
}

#[allow(dead_code)]
fn offset_distance(left: &[f64], right: &[f64]) -> f64 {
    left.iter()
        .zip(right)
        .map(|(left, right)| periodic_difference(*left, *right).abs())
        .sum()
}

#[allow(dead_code)]
fn periodic_difference(left: f64, right: f64) -> f64 {
    let mut difference = (left - right) % 360.0;
    if difference > 180.0 {
        difference -= 360.0;
    } else if difference < -180.0 {
        difference += 360.0;
    }
    difference
}

fn compare_angles(left: &[(f64, f64)], right: &[(f64, f64)]) -> std::cmp::Ordering {
    for (&(left_phi, left_psi), &(right_phi, right_psi)) in left.iter().zip(right) {
        let ordering = left_phi
            .total_cmp(&right_phi)
            .then_with(|| left_psi.total_cmp(&right_psi));
        if !ordering.is_eq() {
            return ordering;
        }
    }
    left.len().cmp(&right.len())
}

fn compare_offsets(left: &[f64], right: &[f64]) -> std::cmp::Ordering {
    for (left, right) in left.iter().zip(right) {
        let ordering = left.total_cmp(right);
        if !ordering.is_eq() {
            return ordering;
        }
    }
    left.len().cmp(&right.len())
}

fn wrap_degrees(value: f64) -> f64 {
    let mut wrapped = value % 360.0;
    if wrapped > 180.0 {
        wrapped -= 360.0;
    } else if wrapped <= -180.0 {
        wrapped += 360.0;
    }
    wrapped
}

/// Squared wrapped (periodic) angular distance between two torsion vectors.
/// Each component is wrapped into [-180, 180) so 175 deg and -170 deg are 15
/// deg apart, not 345.
#[cfg(test)]
fn wrapped_torsion_distance_squared(left: &[f64], right: &[f64]) -> f64 {
    left.iter()
        .zip(right)
        .map(|(a, b)| {
            let d = wrap_degrees(a - b);
            d * d
        })
        .sum()
}

/// PHASE 5: soft, bounded GlycoShape torsion prior.  The objective requires
/// GlycoShape to be a weak prior, never a hard rejection: far-from-native
/// conformations should be penalized, not made impossible.  `E = min_k`
/// `d_theta(theta, theta_k)^2` over the native library, capped at `cap`, gives
/// a bounded penalty that density evidence can always overcome.  This is the
/// "simple bounded soft penalty" the objective explicitly permits.
#[cfg(test)]
fn glycoshape_torsion_prior(torsions: &[f64], native_torsions: &[Vec<f64>], cap: f64) -> f64 {
    let mut best = f64::INFINITY;
    for native in native_torsions {
        if native.len() != torsions.len() {
            continue;
        }
        let distance = wrapped_torsion_distance_squared(torsions, native);
        if distance < best {
            best = distance;
        }
    }
    if best.is_finite() { best.min(cap) } else { cap }
}

