    #[test]
    fn connected_arm_definitions_keep_complete_descendant_subtrees() {
        fn residue(number: i32) -> ResidueId {
            ResidueId {
                chain: "G".into(),
                number,
                insertion_code: None,
            }
        }
        fn branch(parent: i32, child: i32, atom: u32) -> BranchRotation {
            BranchRotation {
                axis: (AtomId(atom), AtomId(atom + 1)),
                moving: Vec::new(),
                residues: vec![residue(child)],
                child_residue: residue(child),
                parent_residue: residue(parent),
                label: format!("{parent}->{child}"),
            }
        }

        // 1 branches to 2 and 3; the 2-arm continues through 4 to 5/6.
        let branches = vec![
            branch(1, 2, 1),
            branch(1, 3, 3),
            branch(2, 4, 5),
            branch(4, 5, 7),
            branch(4, 6, 9),
        ];
        let arms = connected_arm_definitions(&branches);
        let arm_2 = arms
            .iter()
            .find(|arm| arm.root_residue == residue(2))
            .unwrap();
        assert_eq!(
            arm_2.residues.iter().cloned().collect::<BTreeSet<_>>(),
            [residue(2), residue(4), residue(5), residue(6)]
                .into_iter()
                .collect()
        );
        assert_eq!(arm_2.axes, vec![0, 2, 3, 4]);
        let arm_3 = arms
            .iter()
            .find(|arm| arm.root_residue == residue(3))
            .unwrap();
        assert_eq!(arm_3.residues, vec![residue(3)]);
    }

    #[test]
    fn global_arm_torsion_modes_cover_periodic_domain_without_duplicates() {
        fn residue(number: i32) -> ResidueId {
            ResidueId {
                chain: "G".into(),
                number,
                insertion_code: None,
            }
        }
        let arm_three = ConnectedArm {
            label: "alpha16".into(),
            parent_residue: residue(1),
            root_residue: residue(2),
            residues: vec![residue(2), residue(3), residue(4)],
            axes: vec![0, 1, 2], // 3-DOF alpha-1,6 arm
        };
        let modes = global_arm_torsion_modes(&arm_three);
        assert!(
            !modes.is_empty() && modes.len() <= 16,
            "3-DOF global sweep should be a small diverse supplement, got {}",
            modes.len()
        );
        // Every mode has a torsion per axis and wraps into [0,360).
        for mode in &modes {
            assert_eq!(mode.torsions.len(), 3);
            for angle in &mode.torsions {
                assert!((0.0..360.0).contains(&angle.rem_euclid(360.0)));
            }
            // Global modes are never conformer-backed, so they must not be
            // auto-protected (their population is a soft distant-basin prior).
            assert!(mode.context.is_empty());
        }
        // Coarse 30-degree dedup must leave each torsion cell at most one
        // representative, so cell keys are unique.
        let mut cells = BTreeSet::new();
        for mode in &modes {
            let key = mode
                .torsions
                .iter()
                .map(|angle| ((angle.rem_euclid(360.0) / 30.0).round() as i16).rem_euclid(12))
                .collect::<Vec<_>>();
            assert!(cells.insert(key), "duplicate torsion cell emitted");
        }

        // A 2-DOF (alpha-1,3) arm should be no larger than the 3-DOF arm.
        let arm_two = ConnectedArm {
            label: "alpha13".into(),
            parent_residue: residue(1),
            root_residue: residue(5),
            residues: vec![residue(5), residue(6)],
            axes: vec![3, 4],
        };
        let modes_two = global_arm_torsion_modes(&arm_two);
        assert!(!modes_two.is_empty() && modes_two.len() <= modes.len());
    }

