    #[test]
    fn linkage_registration_maps_parent_and_child_anchors_exactly() {
        let source_parent_o = Vec3 {
            x: 0.0,
            y: 0.0,
            z: 0.0,
        };
        let source_child_c1 = Vec3 {
            x: 1.42,
            y: 0.0,
            z: 0.0,
        };
        let source_child_c2 = Vec3 {
            x: 1.90,
            y: 1.15,
            z: 0.20,
        };
        let target_parent_o = Vec3 {
            x: 4.0,
            y: -2.0,
            z: 1.0,
        };
        let target_child_c1 = Vec3 {
            x: 4.0,
            y: -0.58,
            z: 1.0,
        };
        let target_child_c2 = Vec3 {
            x: 2.85,
            y: -0.10,
            z: 1.20,
        };
        let source = pose_frame_from_points(source_parent_o, source_child_c1, source_child_c2)
            .expect("source linkage anchors must be non-collinear");
        let target = pose_frame_from_points(target_parent_o, target_child_c1, target_child_c2)
            .expect("target linkage anchors must be non-collinear");

        let mapped_parent = transform_ring_frame_point(source, target, source_parent_o);
        let mapped_c1 = transform_ring_frame_point(source, target, source_child_c1);
        let mapped_c2 = transform_ring_frame_point(source, target, source_child_c2);
        assert!(distance_vec(mapped_parent, target_parent_o) < 1.0e-10);
        assert!(distance_vec(mapped_c1, target_child_c1) < 1.0e-10);
        assert!(distance_vec(mapped_c2, target_child_c2) < 1.0e-10);

        // A fourth arm atom keeps its source distance to the child anchors;
        // the registration is rigid and therefore cannot distort the
        // transplanted ring/substituent geometry.
        let source_substituent = Vec3 {
            x: 2.40,
            y: 0.55,
            z: -0.35,
        };
        let mapped_substituent = transform_ring_frame_point(source, target, source_substituent);
        assert!(
            (distance_vec(mapped_substituent, mapped_c1)
                - distance_vec(source_substituent, source_child_c1))
            .abs()
                < 1.0e-10
        );
    }

    #[test]
    fn arm_transplant_uses_parent_frame_and_moves_child_linkage() {
        // The source and recipient share the same parent-ring geometry, but
        // the source child is rotated away from the recipient's current
        // child.  A frame built from the current child on both sides would
        // incorrectly leave the child at (12, 0, 0); the parent-linkage
        // registration must carry the source displacement to (12, 2, 0).
        let structure = read_pdb_str(
            "ATOM      1  C1  MAN A   1       0.000   0.000   0.000  1.00  0.00           C\n\
ATOM      2  C2  MAN A   1       1.000   0.000   0.000  1.00  0.00           C\n\
ATOM      3  C3  MAN A   1       0.000   1.000   0.000  1.00  0.00           C\n\
ATOM      4  O3  MAN A   1       0.000   0.000   1.000  1.00  0.00           O\n\
ATOM      5  C1  MAN A   2       2.000   0.000   0.000  1.00  0.00           C\n\
ATOM      6  C2  MAN A   2       3.000   0.000   0.000  1.00  0.00           C\n\
ATOM      7  C3  MAN A   2       2.000   1.000   0.000  1.00  0.00           C\n\
TER\nEND\n",
            &BuildOptions::default(),
        )
        .expect("synthetic parent/child structure must parse");
        let mut source = structure
            .atoms()
            .into_iter()
            .map(|atom| (atom.id, atom.position))
            .collect::<BTreeMap<_, _>>();
        source.insert(
            AtomId(5),
            Vec3 {
                x: 2.0,
                y: 2.0,
                z: 0.0,
            },
        );
        source.insert(
            AtomId(6),
            Vec3 {
                x: 3.0,
                y: 2.0,
                z: 0.0,
            },
        );
        source.insert(
            AtomId(7),
            Vec3 {
                x: 2.0,
                y: 3.0,
                z: 0.0,
            },
        );
        let target = structure
            .atoms()
            .into_iter()
            .map(|atom| {
                let position = Vec3 {
                    x: atom.position.x + 10.0,
                    y: atom.position.y,
                    z: atom.position.z,
                };
                (atom.id, position)
            })
            .collect::<BTreeMap<_, _>>();
        let arm = ConnectedArm {
            label: "test".into(),
            parent_residue: ResidueId {
                chain: "A".into(),
                number: 1,
                insertion_code: None,
            },
            root_residue: ResidueId {
                chain: "A".into(),
                number: 2,
                insertion_code: None,
            },
            residues: vec![ResidueId {
                chain: "A".into(),
                number: 2,
                insertion_code: None,
            }],
            axes: vec![0],
        };
        let branch = BranchRotation {
            axis: (AtomId(5), AtomId(4)),
            moving: vec![AtomId(5), AtomId(6), AtomId(7)],
            residues: arm.residues.clone(),
            child_residue: arm.root_residue.clone(),
            parent_residue: arm.parent_residue.clone(),
            label: "O3-C1 [phi]".into(),
        };
        let registered = transplant_arm_positions(&structure, &source, &target, &arm, &branch)
            .expect("parent-frame registration must succeed");
        let child = registered.get(&AtomId(5)).copied().unwrap();
        assert!((child.x - 12.0).abs() < 1.0e-10);
        assert!((child.y - 2.0).abs() < 1.0e-10);
        assert!(child.z.abs() < 1.0e-10);
    }

